INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('9edb0dcc-a530-443c-a4f1-f6404583c2a0', 'Bicep Curl (Bar)', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Bar Biceps Curl is a curling exercise that isolates your biceps. You''ll also feel your forearms working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Arm strength supports grip, pulling, and pushing in compound movements.', '47211201', '47211201-Bar-Biceps-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Keep your elbows in a fixed position throughout the movement. 2. Curl the weight up by contracting your biceps, squeezing at the top. 3. Lower with control, resisting the weight on the way down. 4. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement. This exercise is excellent for biceps development.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'bicep_curl', 'Bar Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('9ef6626a-1b14-43c9-9d73-9730e2590756', 'Incline Twisting Sit Up', 'Core', 'Bodyweight, Decline Bench', '{"Abs"}'::text[], '{}'::text[], 'This twisting movement focuses on your obliques for a complete core workout. Your hip flexors work as secondary movers, adding to the training stimulus. Using an incline changes the angle of resistance for varied muscle recruitment. A strong core improves posture, protects your spine, and enhances all other lifts.', '70061201', '70061201-Incline-Twisting-Sit-up-(version-2)-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Rotate your torso through the movement pattern for Incline Twisting Sit Up. 2. Control the rotation in both directions—avoid using momentum. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'crunch', 'Incline Twisting Sit Up', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('9ef776d8-3c55-4937-bf08-a8c95fffdb5a', 'Sumo Squat Floor Tap', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '73161201', '73161201-Sumo-Squat-Floor-Tap-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Position yourself on the floor for Sumo Squat Floor Tap. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'squat', 'Sumo Squat Floor Tap', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('9ef934aa-6473-47b6-b5f8-ae1b0b80edf0', 'Lying Hammer Press (Dumbbell)', 'Chest', 'Dumbbells, Flat Bench', '{"Chest"}'::text[], '{}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. Performing this lying down removes momentum for stricter form. Dumbbells allow each arm to work independently, helping correct imbalances. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '24861201', '24861201-Dumbbell-Lying-Hammer-Press-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Hammer Press. 2. Lie down in the appropriate position for Dumbbell Lying Hammer Press. 3. Use a hammer/neutral grip with palms facing each other throughout. 4. Lower the weight toward your chest with control. 5. Press the weight up until your arms are extended (don''t lock elbows). 6. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'squeeze_press', 'Lying Hammer Press', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('9f07c17b-655c-4095-a061-69eee86a08f7', 'Incline Reverse Hyperextension (Resistance Band)', 'Back', 'Resistance Band, Hyperextension Bench', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Resistance Band Incline Reverse Hyperextension is a hip-dominant extension exercise that targets your glutes. The hamstrings, lower back assist throughout the movement, making this a well-rounded exercise. The incline angle shifts emphasis toward the upper portion of the target muscles. Resistance bands provide accommodating resistance that increases through the range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '86981201', '86981201-Resistance-Band-Incline-Reverse-Hyperextension-(ma.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Secure the resistance band appropriately for Resistance Band Incline Reverse Hyperextension. 2. Raise your torso by extending at the lower back/hips. 3. Lower with control, maintaining tension. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'back_extension', 'Incline Reverse Hyperextension', 'good_morning, bird_dog, superman', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('9f09e460-29bc-487e-ab29-b17e90079a49', 'Wide Forward Fold Twist', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Designed to lengthen your hamstrings, the Wide Forward Fold Twist helps improve mobility and prevent stiffness. Your lower back, calves work as secondary movers, adding to the training stimulus. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '87581201', '87581201-Wide-Forward-Fold-Twist-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Rotate your torso through the movement pattern for Wide Forward Fold Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Move into the stretch position for Wide Forward Fold Twist. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'hamstring_stretch', 'Wide Forward Fold Twist', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('9f263689-46be-4295-8c9e-2ddf8c5f3b4f', 'Quick Sumo Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '88891201', '88891201-Quick-Sumo-Squat-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction. Include this in your legs training.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Quick Sumo Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('9f31ea2c-39d3-4d96-bf4d-7071b34187c2', 'Lying Knee Tuck - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Lying Alternating Knee Tuck, focusing on your abs. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '71311201', '71311201-Lying-Alternating-Knee-Tuck-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Alternating Knee Tuck. 2. Alternate between sides/arms/legs with each repetition. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Knee Tuck - Alternating', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('9f3e43a1-695a-4243-aec3-89eeeb012509', 'Plank Pike To Climber', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Strengthen your midsection with this stabilization movement that works your abs. Your shoulders, lower back work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '93441201', '93441201-Plank-Pike-to-Climber-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Plank Pike To Climber', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('9f441df9-0760-42d2-b0b1-db33ce4b3880', 'Incline Single Arm Lateral Raise (Dumbbell)', 'Shoulders', 'Dumbbells, Incline Bench', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'This raising exercise works your lateral delts for improved shoulder strength and aesthetics. The incline angle shifts emphasis toward the upper portion of the target muscles. The dumbbell variation provides freedom of movement and greater range of motion. Shoulder development enhances both performance and upper body aesthetics.', '3231201', '03231201-Dumbbell-Incline-One-Arm-Lateral-Raise_Shoulders-F.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'lateral_raise', 'Incline Single Arm Lateral Raise', 'shoulder_press, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('9f6369cc-d89d-4fae-8186-de8fa3d0f353', 'Half Plyo Squat Jack', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this squatting exercise that develops speed, power, and coordination. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '64031201', '64031201-Half-Plyo-Squat-Jack-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Maintain consistent tempo throughout the set. An effective movement for your plyometrics routine.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'squat', 'Half Plyo Squat Jack', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('9f750c18-971c-450d-a4be-3ff720bea169', 'Run', 'Full Body', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. Cardiovascular exercise improves heart health, endurance, and helps manage weight. Control the negative portion for maximum muscle engagement.', '21961201', '21961201-Run-(female)_Cardio.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Set up in the starting position for Run. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Cardio', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Run', 'cycling, rowing_cardio, jump_rope', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('9f831a27-9226-4e90-827d-db16cb272ab7', 'Twist And Side Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity crunching exercise that challenges your entire body. You''ll also feel your abs working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '77011201', '77011201-Twist-and-Side-Crunch-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum. Ideal for abs strength and endurance.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Twist And Side Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('9f87f1be-05e6-4089-a300-56cf2e313b05', 'Incline Twist Press (Dumbbell)', 'Chest', 'Dumbbells, Incline Bench', '{"Chest"}'::text[], '{"Abs"}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. The abs assist throughout the movement, making this a well-rounded exercise. The incline angle shifts emphasis toward the upper portion of the target muscles. Dumbbells allow each arm to work independently, helping correct imbalances. A well-developed chest contributes to upper body strength and aesthetics.', '106041201', '106041201-Dumbbell-Incline-Twist-Press-(VERSION-2)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Twist Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'russian_twist', 'Incline Twist Press', 'bench_press, chest_fly, shoulder_press, decline_bench_press', FALSE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('9f944d7f-fbeb-454a-b3cc-1e73fdd7e273', 'Incline Twisted Fly (Dumbbell)', 'Chest', 'Dumbbells, Incline Bench', '{"Chest"}'::text[], '{"Abs"}'::text[], 'Build a stronger chest with this flying movement that develops pressing power. The abs assist throughout the movement, making this a well-rounded exercise. Using an incline changes the angle of resistance for varied muscle recruitment. Dumbbells allow each arm to work independently, helping correct imbalances. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '3311201', '03311201-Dumbbell-Incline-Twisted-Fly_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Twisted Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'russian_twist', 'Incline Twisted Fly', 'incline_bench_press, chest_fly, shoulder_press', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('9f952916-a552-4ab7-aec7-1459b8979403', 'Thruster (Dumbbell)', 'Full Body', 'Dumbbells', '{"Full Body"}'::text[], '{"Quads","Shoulders"}'::text[], 'Build leg strength with this thrusting movement focusing on your full body. Secondary activation of your quads, shoulders provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. Leg training boosts metabolism and builds functional, real-world strength.', '29691201', '29691201-Dumbbell-Thruster-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Thruster. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 62, 7, 9, TRUE, FALSE, 'thruster', 'Thruster', 'front_squat, shoulder_press, clean', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('9f9b2f9f-8a85-4e71-9f45-64ad59d285b8', 'Deadlift Jump', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'Build power and athleticism with this high-intensity hip hinge exercise that challenges your entire body. Secondary activation of your glutes, lower back provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '74591201', '74591201-Deadlift-Jump-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Hinge at hips and bend knees to grip the weight. 2. Drive through your heels, extending hips and knees to stand. 3. Lower by reversing the movement with control. 4. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'deadlift', 'Deadlift Jump', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('9fbddf35-9e5b-4dfb-b72d-39edf359c97e', 'RKC Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'This stabilization exercise engages your abs for improved core stability and strength. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '62731201', '62731201-RKC-Plank-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form. Ideal for abs strength and endurance.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'RKC Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('9fc0e2f4-c3af-438e-a25d-c66b9365b7bb', 'Side Bend Stretch (Stick)', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build a stronger core with the Stick Side Bend Stretch, focusing on your abs. You''ll also feel your abs working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '103601201', '103601201-Stick-Side-Bend-Stretch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Set up in the starting position for Stick Side Bend Stretch. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'side_bend', 'Stick Side Bend Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('9fc26456-b345-4be3-8abf-16873c992aaa', 'Single Leg Sliding Floor Bridge Curl (Towel)', 'Arms', 'Towel', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Develop your posterior chain with this curling movement that emphasizes the glutes. The hamstrings assist throughout the movement, making this a well-rounded exercise. Lower body strength improves everything from walking to heavy compound lifts.', '57731201', '57731201-Single-Leg-Sliding-Floor-Bridge-Curl-on-Towel-(fem.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Position yourself on the floor for Single Leg Sliding Floor Bridge Curl On Towel. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'glute_bridge', 'Single Leg Sliding Floor Bridge Curl On Towel', 'hip_thrust, romanian_deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('9fc35022-e4cf-4181-ba57-3dce9b1b06ff', 'Lying Prone Y To T To W', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger back with this movement movement targeting your core. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. A strong back improves posture, prevents injury, and balances pressing movements. Can be modified for beginners or progressed for advanced athletes.', '85461201', '85461201-Lying-Prone-Y-to-T-to-W-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Lie face down with your body in a straight line. 2. Set up in the starting position for Lying Prone Y To T To W. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Prone Y To T To W', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('9fe2971c-5628-4082-a7e4-baa866e3a0bc', 'Hammer Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Dumbbell Hammer Curl is a curling exercise that isolates your biceps. The forearms assist throughout the movement, making this a well-rounded exercise. The dumbbell variation provides freedom of movement and greater range of motion. Arm strength supports grip, pulling, and pushing in compound movements. Excellent for pre-exhausting the target muscle before compound lifts.', '3131201', '03131201-Dumbbell-Hammer-Curl_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Hammer Curl. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'hammer_curl', 'Hammer Curl', 'bicep_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('9fe60802-d1b5-425b-8782-9cc5947ad6f8', 'Seated Triceps Stretch (Chair)', 'Arms', 'Chair', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Designed to lengthen your triceps, the Seated Triceps Stretch On A Chair helps improve mobility and prevent stiffness. Your shoulders work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Include this in your routine for better mobility and reduced muscle tension.', '104681201', '104681201-Seated-Triceps-Stretch-on-a-Chair-(male)_Stretchi.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Triceps Stretch On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 27, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Triceps Stretch On A Chair', 'bicep_curl, dip', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('9fe7a733-c104-40bb-aa96-753c62dc3ea3', 'Incline Triceps Extension (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Cable Incline Triceps Extension targets your triceps through a extension motion. The incline angle shifts emphasis toward the upper portion of the target muscles. The cable setup allows you to adjust the angle of resistance. Arm strength supports grip, pulling, and pushing in compound movements.', '1731201', '01731201-Cable-Incline-Triceps-Extension_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Adjust the cable machine to the correct height and attachment for Cable Incline Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 93, 5, 7, FALSE, TRUE, 'tricep_extension', 'Incline Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('9fec4a89-0dff-452f-8c4a-1fb44affcb06', 'Standing Calf Raise (Machine)', 'Legs', 'Calf Raise Machine', '{"Calves"}'::text[], '{}'::text[], 'The Lever Standing Calf Raise isolates your calf muscles through a raising motion. The standing position engages your core for stability. The machine guides your movement path for safer, more controlled repetitions. Leg training boosts metabolism and builds functional, real-world strength.', '6051201', '06051201-Lever-Standing-Calf-Raise_Calf-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Standing Calf Raise. 2. Stand with feet about shoulder-width apart. 3. Lower your heels below the platform to get a full stretch. 4. Rise up onto your toes as high as possible, squeezing your calves. 5. Lower with control and repeat. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'calf_raise', 'Lever Standing Calf Raise', 'calf_raise, seated_calf_raise', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('9ffb253b-3f7f-45bc-9ea0-5fc5e107f137', 'Bent Over Lat Pulldown (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Band Bent Over Lat Pulldown is a pulling exercise that targets your latissimus dorsi for a wider back. Your biceps, upper back work as secondary movers, adding to the training stimulus. The bent over position requires core engagement to maintain a neutral spine. Resistance bands provide accommodating resistance that increases through the range of motion. Back development is crucial for pulling strength and overall upper body function.', '70451201', '70451201-Band-Bent-Over-Lat-Pulldown-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Secure the resistance band appropriately for Band Bent Over Lat Pulldown. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the bar/handle down toward your upper chest. 4. Drive your elbows down and back, squeezing your lats. 5. Control the weight back up without letting it yank your arms. 6. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', 'Pull Down', 'Pull', 'Compound', 'Bilateral', NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, 'Neutral', 'Standard', 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Bent Over Lat Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('a010125b-ed35-4d79-8c31-2680e661ef8d', 'Glute Bridge Straight Leg Circle - Alternating', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this bridging movement focused on hip extension. Secondary activation of your hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '97161201', '97161201-Glute-Bridge-Alternating-Straight-Leg-Circle-(fema.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Alternate between sides/arms/legs with each repetition. 5. Complete all reps with control before resting. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'romanian_deadlift', 'Glute Bridge Straight Leg Circle - Alternating', 'deadlift, leg_curl, hip_thrust', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a0318cb6-07b8-4177-ba00-80782b5e38e8', 'Standing Wheel Rollout (Ab Wheel)', 'Core', 'Ab Wheel', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Standing Wheel Rollout, focusing on your abs. Your lats, shoulders work as secondary movers, adding to the training stimulus. The standing position engages your core for stability. Building core stability helps with everything from heavy deadlifts to daily activities.', '7961201', '07961201-Standing-Wheel-Rollout_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Wheel Rollout. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'ab_rollout', 'Standing Wheel Rollout', 'plank, crunch, dead_bug', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a039386c-366a-4143-b5d4-acc61e6ce573', 'Standing Quadriceps Stretch (Chair)', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Use this stretch to open up your quads area and enhance overall flexibility. You''ll also feel your hip flexors working to support the movement. Performing this standing challenges your balance and core engagement. Flexibility work like this enhances performance and prevents stiffness.', '92661201', '92661201-Standing-Quadriceps-Stretch-with-a-Chair-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Stand tall with your feet firmly planted. 3. Move into the stretch position for Standing Quadriceps Stretch With A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 27, 2, 6, FALSE, TRUE, 'stretch_general', 'Standing Quadriceps Stretch With A Chair', 'stretch_hip, stretch_hamstring', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a0399f38-7247-4bed-89db-0973ddf6bd22', 'Standing Lean Forward Hamstring Stretch (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'The Standing Lean Forward Hamstring Stretch is a flexibility exercise that targets your hamstrings, helping to release tension and improve range of motion. The lower back assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '84421201', '84421201-Standing-Lean-Forward-Hamstring-Stretch-(female)_S.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand with feet about shoulder-width apart. 2. Move into the stretch position for Standing Lean Forward Hamstring Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 30, 2, 6, FALSE, TRUE, 'hamstring_stretch', 'Standing Lean Forward Hamstring Stretch', 'stretch_hip, stretch_calf, stretch_back', FALSE, 'gymnastic_rings', TRUE, 1, 30, 2, 68, 85, 85, 70),
('a0497937-c5c4-4645-8bd0-5b2a0c5f82eb', 'Ab Swing (Machine)', 'Core', 'Ab Machine', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This swinging exercise engages your abs for improved core stability and strength. The machine guides your movement path for safer, more controlled repetitions. A strong core improves posture, protects your spine, and enhances all other lifts.', '65611201', '65611201-Lever-Ab-Swing-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Ab Swing. 2. Hinge at your hips, letting the weight swing back between your legs. 3. Explosively drive hips forward, propelling the weight forward/up. 4. Let gravity bring it back as you hinge for the next rep. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'core_exercise', 'Lever Ab Swing', 'plank, crunch, leg_raise', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('a04a19be-ccc6-49f1-a278-5965088476c3', 'Standing Air Bike', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '42751201', '42751201-Standing-Air-Bike-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Air Bike. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 37, 9, 8, FALSE, TRUE, 'cycling', 'Standing Air Bike', 'crunch, russian_twist, leg_raise', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('a05e03a0-902a-4be5-8c6c-481980b06379', 'Seated Opposite Grab (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. Being seated provides stability, allowing you to focus on the working muscles. A strong core improves posture, protects your spine, and enhances all other lifts.', '94131201', '94131201-Sitting-Opposite-Grab-on-a-Chair-(VERSION-2)-(fema.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep. This exercise is excellent for abs development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'core_exercise', 'Seated Opposite Grab On A Chair', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a061ea18-5d22-40fb-a09e-e4333750794b', 'Ring Eccentric Leg Curl With Yoga Block And Towel (Gymnastic Rings)', 'Legs', 'Gymnastic Rings, Towel, Yoga Block', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Strengthen the back of your thighs with this curling exercise. Your calves work as secondary movers, adding to the training stimulus. Leg training boosts metabolism and builds functional, real-world strength. This is a great exercise for all fitness levels with proper scaling.', '78711201', '78711201-Ring-Eccentric-Leg-Curl-with-yoga-block-and-towel_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Curl your heels toward your glutes by bending at the knees. 2. Squeeze your hamstrings at peak contraction. 3. Extend legs back out with control. 4. Focus on a slow, controlled lowering phase (3-5 seconds). 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'leg_curl', 'Ring Eccentric Leg Curl With Yoga Block And Towel', 'romanian_deadlift, hip_thrust', FALSE, 'gymnastic_rings', TRUE, 1, 30, 2, 68, 85, 85, 70),
('a06d6706-a84e-4a60-87cf-68dc7f2e7fb6', 'Standing Backhand And Forehand Push', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics. Quality repetitions are more important than quantity.', '94751201', '94751201-Standing-Backhand-And-Forehand-Push-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Backhand And Forehand Push. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_exercise', 'Standing Backhand And Forehand Push', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a06ef8fd-351b-4c6b-a6e9-190b568d33ef', 'Seated Leg Extension (Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{}'::text[], 'Target the front of your thighs with this extension exercise for quad development. The seated position helps isolate the target muscles by removing momentum. Bands are joint-friendly and portable, perfect for any training environment. Leg training boosts metabolism and builds functional, real-world strength.', '35191201', '35191201-Band-Seated-Leg-Extension-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Seated Leg Extension. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend your legs until straight, squeezing your quads at the top. 4. Lower with control back to the starting position. 5. Complete all reps with control before resting. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 87, 5, 7, FALSE, TRUE, 'leg_extension', 'Seated Leg Extension', 'squat, leg_press, lunge', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('a0775edb-ade0-4396-94f4-34718bed9e39', 'Shrimp Slight Squat Supported Wall (Wall)', 'Legs', 'Wall', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. You''ll also feel your glutes, hamstrings working to support the movement. Leg training boosts metabolism and builds functional, real-world strength. Keep your core engaged throughout the exercise. Consistency with this movement will yield noticeable results.', '97171201', '97171201-Shrimp-Slight-Squat-Supported-Wall-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Position yourself at the appropriate distance from a wall. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'squat', 'Shrimp Slight Squat Supported Wall', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a093ba04-b02c-4302-8ba1-6e2b585bc5cb', 'Weighted Bar Standing Lateral Raise', 'Shoulders', 'Bodyweight', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'The Weighted Bar Standing Lateral Raise is a raising exercise that targets your lateral delts for shoulder development. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Shoulder development enhances both performance and upper body aesthetics.', '80201201', '80201201-Weighted-Bar-Standing-Lateral-Raise-(male)_Shoulde.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Stand with feet about shoulder-width apart. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'lateral_raise', 'Weighted Bar Standing Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a0a3f5eb-6ad6-47d0-b097-5fe6d8d5d685', 'Seated Rotation Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your full body, the Seated Rotation Stretch helps improve mobility and prevent stiffness. The seated position helps isolate the target muscles by removing momentum. Include this in your routine for better mobility and reduced muscle tension.', '51351201', '51351201-Seated-Rotation-Stretch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Rotation Stretch. 3. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Rotation Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a0ad30cb-da91-452d-a0f7-0dac02e98544', 'Standing Balance Hip Rotation', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Build leg strength with this rotation movement focusing on your full body. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '67501201', '67501201-Standing-Balance-Hip-Rotation-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand tall with your feet firmly planted. 2. Rotate your torso through the movement pattern for Standing Balance Hip Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'balance', 'Standing Balance Hip Rotation', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a0b4fd15-c19f-46d2-83ed-c1859baf84ff', 'Side To Side Knee Tuck', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Side To Side Knee Tuck, focusing on your abs. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '56131201', '56131201-Side-to-Side-Knee-Tuck-(Male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Set up in the starting position for Side To Side Knee Tuck. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Side To Side Knee Tuck', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a0b5a27b-e302-4b19-811f-cc578da8009f', 'Bent Over Reverse Fly To Hammer Curl (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Biceps"}'::text[], '{"Upper Back","Traps"}'::text[], 'Build balanced shoulders by working the posterior delts with this curling exercise. The upper back assist throughout the movement, making this a well-rounded exercise. The bent over position requires core engagement to maintain a neutral spine. Using dumbbells requires more stabilization than barbell variations. Back development is crucial for pulling strength and overall upper body function.', '74751201', '74751201-Dumbbell-Bent-Over-Reverse-Fly-to-Hammer-Curl-(mal.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Bent Over Reverse Fly To Hammer Curl. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Use a hammer/neutral grip with palms facing each other throughout. 4. Keep your elbows in a fixed position throughout the movement. 5. Curl the weight up by contracting your biceps, squeezing at the top. 6. Lower with control, resisting the weight on the way down. 7. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'rear_delt', 'Bent Over Reverse Fly To Hammer Curl', 'bench_press, incline_bench_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('a0bb7ba9-d520-4e22-bd4a-7bfc8ef27e15', 'Zercher Squat Hold (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Strengthen your midsection with this squatting movement that works your quads. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Using a barbell provides stability for progressive overload. Core strength is foundational for athletic performance and injury prevention.', '14461201', '14461201-Barbell-Zercher-Squat-Hold_Isometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Zercher Squat Hold. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Hold the position for the prescribed time, maintaining tension.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'squat', 'Zercher Squat Hold', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'barbell', TRUE, 3, 90, 4, 95, 80, 65, 95),
('a0be3128-e1a8-494a-b905-9c40e9f62306', 'Face Pull (TRX)', 'Shoulders', 'TRX', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'The Suspender Face Pull is a pulling exercise that targets your delts for shoulder development. Secondary activation of your upper back, rotator cuff provides additional muscle engagement. Suspension training adds instability, increasing core activation throughout. Shoulder development enhances both performance and upper body aesthetics.', '11131201', '11131201-Suspender-Face-Pull-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Face Pull. 2. Pull the rope toward your face, separating your hands as you pull. 3. Squeeze your rear delts and upper back at peak contraction. 4. Return with control, maintaining cable tension. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'face_pull', 'Suspender Face Pull', 'rear_delt_fly, bent_over_row, lateral_raise', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('a0c769e7-5b38-42a9-9f29-e36773e0e618', 'Overhead Knee Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build power and athleticism with this high-intensity raising exercise that challenges your entire body. Secondary activation of your hip flexors provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '81751201', '81751201-Overhead-Knee-Raise-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Raise the weight in the prescribed direction for Overhead Knee Raise. 2. Lower with control, maintaining tension throughout. 3. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Overhead Knee Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a0cfaa58-30a8-48f7-bcae-538802ddca22', 'Seated Opposite Touch (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Seated Opposite Touch On A Chair, focusing on your abs. The seated position helps isolate the target muscles by removing momentum. Core strength is foundational for athletic performance and injury prevention.', '81961201', '81961201-Sitting-Opposite-Touch-on-a-Chair-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Opposite Touch On A Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a0d0d212-134b-4bf3-9143-56bf4e5ea1a6', 'Side Lying Hip Circle', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build leg strength with this movement movement focusing on your delts. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '63111201', '63111201-Side-Lying-Hip-Circle-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Lie on your side with your body aligned. 2. Set up in the starting position for Side Lying Hip Circle. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_circle', 'Side Lying Hip Circle', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a0d5af26-d459-414c-a4c4-60b16e863fb2', 'Short Pendulum Side Leg Lift', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Short Pendulum Side Leg Lift builds reactive power and improves conditioning. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '99021201', '99021201-Short-Pendulum-Side-Leg-Lift-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Set up in the starting position for Short Pendulum Side Leg Lift. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Short Pendulum Side Leg Lift', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a0e54bf2-6052-4725-ba0e-82987b8615a1', 'Standing Lat Pushdown Rope (Cable)', 'Arms', 'Cables', '{"Lats"}'::text[], '{"Chest","Shoulders"}'::text[], 'This pushing exercise emphasizes your lats for improved back development. The standing position engages your core for stability. Cable resistance creates smooth, continuous muscle engagement. A strong back improves posture, prevents injury, and balances pressing movements.', '12291201', '12291201-Cable-Standing-Lat-Pushdown-(rope-equipment)_Back-.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Lat Pushdown. 2. Begin in a standing position with good posture. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 54, 5, 7, FALSE, TRUE, 'tricep_pushdown', 'Standing Lat Pushdown', 'tricep_extension, close_grip_bench, dip', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('a0e5bb2e-c33a-4eee-a6cd-51f782bbded6', 'Ski Runners', 'Full Body', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning. This variation is excellent for building mind-muscle connection.', '55421201', '55421201-Ski-Runners-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Set up in the starting position for Ski Runners. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Ski Runners', 'cycling, rowing_cardio, jump_rope', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a0f2cd12-6d14-40c1-a73e-c8da7483587b', 'Row - Reverse Grip (Dumbbell)', 'Back', 'Dumbbells', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Dumbbell Reverse Grip Row is a rowing exercise that builds thickness in your upper back. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. Dumbbells allow each arm to work independently, helping correct imbalances. Back development is crucial for pulling strength and overall upper body function.', '23271201', '23271201-Dumbbell-Reverse-Grip-Row-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Reverse Grip Row. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'general_exercise', 'Row - Reverse Grip', 'Row - Reverse Grip', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('a108e7e0-b0c0-4d8b-b245-358a7c8c53cb', 'Y Raise (TRX)', 'Shoulders', 'TRX', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'Build stronger shoulders with this raising movement focusing on your delts. Secondary activation of your upper back provides additional muscle engagement. The TRX allows you to adjust difficulty by changing your body angle. Shoulder development enhances both performance and upper body aesthetics.', '95081201', '95081201-Suspender-Y-Raise-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Y Raise. 2. Raise the weight in the prescribed direction for Suspender Y Raise. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'lateral_raise', 'Suspender Y Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'trx', FALSE, 3, 60, 2, 68, 85, 85, 70),
('a110668e-791b-49ab-820f-45485bdbcf18', 'Glute Abductors Press (Machine)', 'Legs', 'Hip Abductor/Adductor Machine', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this pressing movement focused on hip extension. You''ll also feel your glutes working to support the movement. The fixed path allows you to focus purely on muscular effort. Lower body strength improves everything from walking to heavy compound lifts.', '66171201', '66171201-Lever-Glute-Abductors-Press-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Glute Abductors Press. 2. Execute the pressing motion for Lever Glute Abductors Press, extending through the target muscles. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'hip_abduction', 'Lever Glute Abductors Press', 'hip_adduction, glute_bridge, clamshell', TRUE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('a12b2dbc-b9e1-4d68-9c32-850e18de9db5', 'Forward Fold And Rock', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Use this stretch to open up your hamstrings area and enhance overall flexibility. You''ll also feel your lower back, calves working to support the movement. Include this in your routine for better mobility and reduced muscle tension.', '85521201', '85521201-Forward-Fold-and-Rock-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Move into the stretch position for Forward Fold And Rock. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hamstring_stretch', 'Forward Fold And Rock', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a12b348e-020c-4547-82b8-e55e5e7073f6', 'Inverted Chin Curl With Bent Knee (Chair)', 'Arms', 'Chair', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. You''ll also feel your forearms working to support the movement. Dedicated arm training builds both strength and muscular definition.', '71041201', '71041201-Inverted-Chin-Curl-with-Bent-Knee-between-Chairs-(.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 55, 5, 7, FALSE, TRUE, 'general_exercise', 'Inverted Chin Curl With Bent Knee Between Chairs', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a13911a1-9bc1-4a60-8bef-ff78aecb14b6', 'Side Wall Plank (Wall)', 'Core', 'Wall', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'The Side Wall Plank is a core stabilization exercise that primarily targets your abs. Secondary activation of your shoulders, lower back provides additional muscle engagement. A strong core improves posture, protects your spine, and enhances all other lifts.', '73861201', '73861201-Side-Wall-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Position yourself at the appropriate distance from a wall. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'plank', 'Side Wall Plank', 'side_plank, dead_bug, hollow_hold', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('a13bc400-ba84-4b90-b78f-d0c1975b3180', 'Deep Breathe Flaps Plyo Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Deep Breathe Flaps Plyo Squat is a squatting exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '59541201', '59541201-Deep-Breathe-Flaps-Plyo-Squat-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form. An effective movement for your legs routine.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'breathing', 'Deep Breathe Flaps Plyo Squat', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('a155533f-7f32-4e78-a6d7-7e70eea94d70', 'Horizontal Single Leg Press (Machine)', 'Legs', 'Leg Press Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this pressing exercise for quad development. The glutes assist throughout the movement, making this a well-rounded exercise. The machine guides your movement path for safer, more controlled repetitions. Leg training boosts metabolism and builds functional, real-world strength.', '8831201', '08831201-Lever-Horizontal-One-leg-Press_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Horizontal One Leg Press. 2. Position your feet on the platform and release the safety. 3. Lower the weight by bending your knees, then press back up powerfully. 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 83, 7, 9, TRUE, FALSE, 'leg_press', 'Lever Horizontal Single Leg Press', 'squat, hack_squat, lunge', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('a15f5e2e-1de0-4506-a165-33920ca5de24', 'Walking Arms Circle', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Walking Arms Circle builds reactive power and improves conditioning. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '99161201', '99161201-Walking-Arms-Circle-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Set up in the starting position for Walking Arms Circle. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'walking', 'Walking Arms Circle', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('a16d88f0-f137-484d-bb5f-a76dce0951f4', 'Power Clean (Barbell)', 'Full Body', 'Barbell', '{"Full Body"}'::text[], '{"Quads","Glutes","Traps"}'::text[], 'Build total body strength and coordination with this multi-joint movement movement. You''ll also feel your quads, glutes, traps working to support the movement. Barbells enable bilateral loading for building raw strength. Full body exercises are time-efficient and build functional, real-world strength.', '52851201', '52851201-Barbell-Power-Clean-(female)_Weightlifting_.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Grip a barbell with hands at the appropriate width for Barbell Power Clean. 2. Explosively pull the weight upward from the starting position. 3. Pull yourself under the weight and catch it at shoulder level. 4. Stand to complete the lift, then lower with control. 5. Perform the concentric (lifting) phase explosively with maximum effort. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 9, NULL, TRUE, NULL, 'Strength', 62, 7, 9, TRUE, FALSE, 'clean', 'Power Clean', 'clean, hang_clean, deadlift', FALSE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('a178de99-2bc8-4adc-927e-75b7d30a2bf4', 'Goblet Squat (Kettlebell)', 'Legs', 'Kettlebell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes, hamstrings provides additional muscle engagement. The kettlebell grip position adds a unique training stimulus. Strong legs are the foundation for athletic performance and functional fitness.', '5341201', '05341201-Kettlebell-Goblet-Squat_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Select an appropriately weighted kettlebell for Kettlebell Goblet Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 93, 7, 8, TRUE, TRUE, 'goblet_squat', 'Goblet Squat', 'squat, front_squat, lunge', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('a17e7331-7724-489f-b49f-00eff26c18d3', 'Lying Curl - Close Grip (Cable)', 'Arms', 'Cables', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Secondary activation of your forearms provides additional muscle engagement. The lying position provides back support and helps isolate the target muscles. Cable resistance creates smooth, continuous muscle engagement. Arm strength supports grip, pulling, and pushing in compound movements.', '1821201', '01821201-Cable-Lying-Close-Grip-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Adjust the cable machine to the correct height and attachment for Cable Lying Close Grip Curl. 2. Lie down in the appropriate position for Cable Lying Close Grip Curl. 3. Use a close/narrow grip (hands closer than shoulder-width). 4. Keep your elbows in a fixed position throughout the movement. 5. Curl the weight up by contracting your biceps, squeezing at the top. 6. Lower with control, resisting the weight on the way down. 7. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'bicep_curl', 'Lying Curl - Close Grip', 'Lying Curl - Close Grip', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('a181ae8e-e273-4dbb-b851-a4b11f676acf', 'Partner Shuffle', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Partner Shuffle builds reactive power and improves conditioning. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '59911201', '59911201-Partner-Shuffle-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Set up in the starting position for Partner Shuffle. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'shuffle', 'Partner Shuffle', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('a1834d6f-9d10-4d8c-b8a1-7c01dd71ae9c', 'Lying Side To Side Roll (Stability Ball)', 'Core', 'Stability Ball', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your core. Performing this lying down removes momentum for stricter form. Using a ball requires constant core engagement to maintain balance. Core strength is foundational for athletic performance and injury prevention.', '93271201', '93271201-Lying-Side-to-Side-Roll-on-Stability-Ball-(female).mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Position the stability ball as needed for Lying Side To Side Roll. 2. Lie on your side with your body aligned. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Side To Side Roll', 'plank, crunch, leg_raise', FALSE, 'stability_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a18fd1a2-5b84-458a-ae5d-0c5274daa271', 'Air Punches March', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Hip Flexors"}'::text[], 'A challenging plyometric exercise, the Air Punches March builds reactive power and improves conditioning. Secondary activation of your hip flexors provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '55501201', '55501201-Air-Punches-March-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Set up in the starting position for Air Punches March. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting. Keep your core engaged for stability.', NULL, 'Push', 'Compound', 'Bilateral (Alternating)', NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'marching', 'Air Punches March', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a1a45fed-9715-43ae-9429-a52a9e7d3b6e', 'Plyo Side Lunge Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'The Plyo Side Lunge Stretch is a lunging exercise that primarily loads your quadriceps. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '6461201', '06461201-Plyo-Side-Lunge-Stretch-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Step to the side, bending that knee while keeping the other leg straight. 2. Push through your front/working leg to return to the starting position. 3. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 60, 9, 8, TRUE, TRUE, 'hip_stretch', 'Plyo Side Lunge Stretch', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('a1b54e6b-86d2-4070-afac-20064097334a', 'Single Leg Hip Thrust (Barbell)', 'Legs', 'Barbell', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'Develop your posterior chain with this thrusting movement that emphasizes the glutes. The hamstrings assist throughout the movement, making this a well-rounded exercise. The barbell allows you to handle heavier loads for maximum strength gains. Strong legs are the foundation for athletic performance and functional fitness.', '10611201', '10611201-Barbell-one-leg-hip-thrust_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Grip a barbell with hands at the appropriate width for Barbell One Leg Hip Thrust. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'hip_thrust', 'Single Leg Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('a1b77f3f-822a-4e19-8a6b-6f82849e486f', 'Seated Single Arm Chest Press (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Cable Seated Single Arm Chest Press is a pressing exercise that targets your chest muscles. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Cable resistance creates smooth, continuous muscle engagement. A well-developed chest contributes to upper body strength and aesthetics.', '79271201', '79271201-Cable-Seated-Single-Arm-Chest-Press-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Single Arm Chest Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'bench_press', 'Seated Single Arm Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('a1b983ab-715e-4e46-b8b7-17cc626341b1', 'Incline Single Arm Press (Dumbbell)', 'Chest', 'Dumbbells, Incline Bench', '{"Chest"}'::text[], '{}'::text[], 'Target your chest with the Dumbbell Incline One Arm Press, an effective pressing movement for upper body strength. The incline angle shifts emphasis toward the upper portion of the target muscles. Dumbbells allow each arm to work independently, helping correct imbalances. A well-developed chest contributes to upper body strength and aesthetics.', '12811201', '12811201-Dumbbell-Incline-One-Arm-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:28.851102+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'arm_exercise', 'Incline Single Arm Press', 'bench_press, chest_fly, shoulder_press, decline_bench_press', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('a1e178da-2724-4569-8fa1-b7393a0140bb', 'Tiger Yoga Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this movement stretch that helps restore range of motion. Include this in your routine for better mobility and reduced muscle tension. Perfect for including in both strength and hypertrophy programs.', '44061201', '44061201-Tiger-Yoga-Pose_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Move into the stretch position for Tiger Yoga Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Tiger Yoga Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a1e1b6f6-09c7-4036-9d76-14eb9af44ddb', 'Kneeling Hip Flexor Frontal', 'Legs', 'Bodyweight', '{"Hip Flexors"}'::text[], '{}'::text[], 'Use this stretch to open up your hip flexors area and enhance overall flexibility. The kneeling position adds a core stability challenge. Include this in your routine for better mobility and reduced muscle tension.', '78611201', '78611201-Kneeling-Hip-Flexor-Frontal-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Move into the stretch position for Kneeling Hip Flexor Frontal. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_stretch', 'Kneeling Hip Flexor Frontal', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a1e31510-4b5c-4958-9b5c-35185b917959', 'Side To Side Skandasana Yoga Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Side To Side Skandasana Yoga Pose is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Flexibility work like this enhances performance and prevents stiffness.', '84981201', '84981201-Side-to-side-Skandasana-Yoga-Pose-(female)_Stretch.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Move into the stretch position for Side To Side Skandasana Yoga Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Side To Side Skandasana Yoga Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a1ece54d-5468-457e-8cc0-4cce75bba8b4', 'Seated Triceps Extension (EZ Bar)', 'Arms', 'EZ Bar, Flat Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. Being seated provides stability, allowing you to focus on the working muscles. Barbells enable bilateral loading for building raw strength. Dedicated arm training builds both strength and muscular definition.', '97351201', '97351201-EZ-Barbell-Seated-Triceps-Extension-(female)_Upper.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Grip a barbell with hands at the appropriate width for EZ Barbell Seated Triceps Extension. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Complete all reps with control before resting. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'tricep_extension', 'EZ Seated Triceps Extension', 'EZ Seated Triceps Extension', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('a1f5df00-bb50-404b-9b8b-e4ae4017cd94', 'Seated Russian Twist (Chair)', 'Core', 'Chair', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Seated Russian Twist On A Chair is a lower body twisting exercise that targets your obliques. Your abs work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Strong legs are the foundation for athletic performance and functional fitness.', '82031201', '82031201-Sitting-Russian-Twist-on-a-Chair-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Rotate your torso through the movement pattern for Seated Russian Twist On A Chair. 4. Control the rotation in both directions—avoid using momentum. 5. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 35, 5, 7, FALSE, TRUE, 'russian_twist', 'Seated Russian Twist On A Chair', 'crunch, plank, leg_raise, wood_chop', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a203fb54-9683-40b1-b0ca-1fb34fe5b9d6', 'Pull Through (Resistance Band)', 'Legs', 'Resistance Band, Anchor Point', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Develop your posterior chain with this pulling movement that emphasizes the glutes. The hamstrings assist throughout the movement, making this a well-rounded exercise. The band creates increasing tension as it stretches, challenging the lockout. Strong legs are the foundation for athletic performance and functional fitness.', '58371201', '58371201-Resistance-Band-Pull-Through-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Pull Through. 2. Set up in the starting position for Resistance Band Pull Through. 3. Execute the movement with proper form, focusing on your glutes. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'pull_through', 'Pull Through', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('a2093edc-eb53-47ac-90ec-b796aadad071', 'Floor Fly (Dumbbell)', 'Chest', 'Dumbbells', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Dumbbell Floor Fly is a flying exercise that targets your chest muscles. You''ll also feel your front delts working to support the movement. Using dumbbells requires more stabilization than barbell variations. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '97291201', '97291201-Dumbbell-Floor-Fly-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Floor Fly. 2. Position yourself on the floor for Dumbbell Floor Fly. 3. With a slight bend in your elbows, move the weight in a wide arc. 4. Squeeze your chest muscles at the center/top of the movement. 5. Return with control, feeling the stretch at the bottom. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'chest_fly', 'Floor Fly', 'bench_press, incline_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('a21829a7-2b2c-4a96-84b9-014cf8828d06', 'Twisted Leg Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this raising exercise that strengthens your obliques. You''ll also feel your hip flexors working to support the movement. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '28011201', '28011201-Twisted-Leg-Raise-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Rotate your torso through the movement pattern for Twisted Leg Raise. 2. Control the rotation in both directions—avoid using momentum. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Twisted Leg Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a229469e-df3b-4b46-9fd3-6a1a839efa40', 'Floor Hyperextension', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Floor Hyperextension provides a deep stretch for your glutes, ideal for recovery and mobility work. Secondary activation of your hamstrings, lower back provides additional muscle engagement. Flexibility work like this enhances performance and prevents stiffness.', '28441201', '28441201-Floor-Hyperextension-(VERSION-2)_Pilates_.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Position yourself on the floor for Floor Hyperextension. 2. Raise your torso by extending at the lower back/hips. 3. Lower with control, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'back_extension', 'Floor Hyperextension', 'good_morning, bird_dog, superman', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a22c4e89-2f30-41af-83ec-821857fdc3f8', 'Lying Feet Open And Close - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this movement movement focusing on your core. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '85441201', '85441201-Lying-Alternate-Feet-Open-and-Close-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Alternate Feet Open And Close. 2. Alternate between sides/arms/legs with each repetition. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Feet Open And Close - Alternating', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a23b5eb6-2afb-404e-aab7-5f8ac42f3a47', 'Side To Side Garland Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Side To Side Garland Pose is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Flexibility work like this enhances performance and prevents stiffness.', '81611201', '81611201-Side-to-Side-Garland-Pose-(female)_Stretching-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Move into the stretch position for Side To Side Garland Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'hip_stretch', 'Side To Side Garland Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a23cefd9-f866-4afe-9b90-1a09f7a9f0e7', 'Crossed Legs Hip Stretch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Target your hips with this stretching stretch that helps restore range of motion. You''ll also feel your glutes working to support the movement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '75731201', '75731201-Crossed-Legs-Hip-Stretch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Move into the stretch position for Crossed Legs Hip Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_stretch', 'Crossed Legs Hip Stretch', 'stretch_hamstring, stretch_glute, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a23d323b-654b-4344-a20c-d48864fa6b6e', 'Side Step L Pose', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Side Step L Pose is an explosive exercise that combines cardiovascular training with dynamic stepping movements. Great for improving athletic performance, burning calories, and building conditioning.', '86291201', '86291201-Side-Step-L-Pose-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step L Pose. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'general_exercise', 'Side Step L Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a24a5c9f-47b7-43d1-8bb0-59a4dbc75617', 'Standing Shoulder Medial And Lateral Rotation', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{}'::text[], 'Develop functional strength with the Standing Shoulder Medial And Lateral Rotation, a comprehensive rotation exercise. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Compound movements like this develop coordination, power, and overall fitness.', '88421201', '88421201-Standing-Shoulder-Medial-and-Lateral-Rotation-(fem.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Begin in a standing position with good posture. 2. Rotate your torso through the movement pattern for Standing Shoulder Medial And Lateral Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_exercise', 'Standing Shoulder Medial And Lateral Rotation', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a25aa0c7-f74c-4865-8208-c553353d8aed', 'Seated Core Twist (Chair)', 'Core', 'Chair', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Seated Core Twist On A Chair targets your obliques through a twisting motion, building rotational core strength. You''ll also feel your abs working to support the movement. The seated position helps isolate the target muscles by removing momentum. Core strength is foundational for athletic performance and injury prevention.', '90951201', '90951201-Sitting-Core-Twist-on-a-Chair-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Rotate your torso through the movement pattern for Seated Core Twist On A Chair. 4. Control the rotation in both directions—avoid using momentum. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 35, 5, 7, FALSE, TRUE, 'russian_twist', 'Seated Core Twist On A Chair', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a26803a1-c148-4578-9994-5f270009edbd', 'Hip Circle With Hula Hoop', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities. Start with lighter weight to master the movement pattern.', '55261201', '55261201-Hip-Circle-with-Hula-Hoop_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Set up in the starting position for Hip Circle With Hula Hoop. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_circle', 'Hip Circle With Hula Hoop', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a26aa0af-24af-4fd4-b2e1-ca96ed5bbe7a', 'Shuffle Leg Lift', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning. Keep your core engaged throughout the exercise.', '55991201', '55991201-Shuffle-Leg-Lift-(Male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Set up in the starting position for Shuffle Leg Lift. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'shuffle', 'Shuffle Leg Lift', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('a27e739b-05ed-4d81-842d-a78fe8eca11c', 'Deadlift (Smith Machine)', 'Back', 'Smith Machine', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. The glutes, lower back assist throughout the movement, making this a well-rounded exercise. The machine guides your movement path for safer, more controlled repetitions. Strong legs are the foundation for athletic performance and functional fitness.', '7521201', '07521201-Smith-Deadlift_Hips-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'deadlift', 'Smith Deadlift', 'Deadlift', FALSE, 'smith_machine', FALSE, 4, 120, 6, 80, 75, 20, 88),
('a29aabb4-8387-44fc-8b31-4729bee2b4d6', 'Seated Bicep Curl (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Dumbbell Seated Biceps Curl is a curling exercise that isolates your biceps. You''ll also feel your forearms working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Dumbbells allow each arm to work independently, helping correct imbalances. Dedicated arm training builds both strength and muscular definition.', '16771201', '16771201-Dumbbell-Seated-Bicep-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Biceps Curl. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'bicep_curl', 'Seated Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('a29b5108-9ce7-4c18-9b40-27b59b00b365', 'Standing Triple Pec Dec Pulse', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build total body strength and coordination with this multi-joint movement movement. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Full body exercises are time-efficient and build functional, real-world strength. A staple exercise that belongs in most training programs.', '94331201', '94331201-Bodyweight-Standing-Triple-Pec-Dec-Pulse-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:31.60311+00', '1. Begin in a standing position with good posture. 2. At the bottom or top, pulse up and down in small movements before completing the rep. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'pulse', 'Standing Triple Pec Dec Pulse', 'bench_press, chest_fly, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a2a4e9b3-5ac9-4569-adc9-5ec9542dc5f3', 'Sicilian Roll Up', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Sicilian Roll Up, focusing on your abs. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '85281201', '85281201-Sicilian-Roll-Up-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Set up in the starting position for Sicilian Roll Up. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Sicilian Roll Up', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a2ab9328-9196-422b-a89b-85065292dc78', 'Kneeling Clock Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pushing movement that develops pressing power. Your triceps, front delts work as secondary movers, adding to the training stimulus. The kneeling position adds a core stability challenge. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '65011201', '65011201-Kneeling-Clock-Push-Up-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Kneeling Clock Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a2adb826-f511-4223-b42c-0a6fa372ce54', 'Sled Calf Press On Leg Press (Machine)', 'Legs', 'Leg Press Machine', '{"Calves"}'::text[], '{}'::text[], 'The Sled Calf Press On Leg Press isolates your calf muscles through a pressing motion. Secondary activation of your glutes provides additional muscle engagement. Leg training boosts metabolism and builds functional, real-world strength.', '22121201', '22121201-Sled-Calf-Press-On-Leg-Press-(female)_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Position your feet on the platform and release the safety. 2. Lower the weight by bending your knees, then press back up powerfully. 3. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 80, 7, 9, TRUE, FALSE, 'calf_raise', 'Sled Calf Press On Leg Press', 'squat, leg_extension, leg_curl, hack_squat, lunge', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('a2bd7120-0dea-41d8-b71a-05e62cdd6977', 'Wall Split (Wall)', 'Full Body', 'Wall', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Include this in your routine for better mobility and reduced muscle tension. Can be modified for beginners or progressed for advanced athletes.', '97681201', '97681201-Wall-Split-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Position yourself at the appropriate distance from a wall. 2. Move into the stretch position for Wall Split. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'general_exercise', 'Wall Split', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a2bf611f-fe66-4d2d-a569-5d3992dc6280', 'Incline Rear Delt Fly With Back Support (Cable)', 'Shoulders', 'Cables', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'This flying exercise works your rear delts for improved shoulder strength and aesthetics. Your upper back work as secondary movers, adding to the training stimulus. Using an incline changes the angle of resistance for varied muscle recruitment. The cable setup allows you to adjust the angle of resistance. Strong shoulders improve overhead strength and support nearly all upper body movements.', '75921201', '75921201-Cable-Incline-Rear-Delt-Fly-with-Back-Support-(mal.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Adjust the cable machine to the correct height and attachment for Cable Incline Rear Delt Fly With Back Support. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 83, 5, 7, FALSE, TRUE, 'rear_delt', 'Incline Rear Delt Fly With Back Support', 'incline_bench_press, chest_fly, shoulder_press', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('a2c125a2-7fe1-4f54-a151-202b528ca87a', 'Incline Single Arm Hammer Press On Exercise (Dumbbell)', 'Chest', 'Dumbbells, Incline Bench', '{"Chest"}'::text[], '{"Triceps"}'::text[], 'The Dumbbell Incline One Arm Hammer Press On Exercise is a pressing exercise that targets your chest muscles. You''ll also feel your triceps working to support the movement. Using an incline changes the angle of resistance for varied muscle recruitment. Dumbbells allow each arm to work independently, helping correct imbalances. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '16201201', '16201201-Dumbbell-Incline-One-Arm-Hammer-Press-on-Exercise-.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'squeeze_press', 'Incline Single Arm Hammer Press On Exercise', 'bench_press, chest_fly, shoulder_press, decline_bench_press', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('a2c3d696-6823-406e-8fec-d081b306030f', 'Upper Chest Crossovers (Cable)', 'Full Body', 'Cables', '{"Full Body"}'::text[], '{"Shoulders","Core"}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. You''ll also feel your shoulders, core working to support the movement. The cable setup allows you to adjust the angle of resistance. Great for improving athletic performance, burning calories, and building conditioning.', '12701201', '12701201-Cable-Upper-Chest-Crossovers_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Adjust the cable machine to the correct height and attachment for Cable Upper Chest Crossovers. 2. Set up in the starting position for Cable Upper Chest Crossovers. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'chest_fly', 'Upper Chest Crossovers', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('a2caefd3-1634-435c-ae28-620058b2b765', 'Deep Squat Head To Floor', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Use this stretch to open up your quads area and enhance overall flexibility. You''ll also feel your glutes, hamstrings working to support the movement. Include this in your routine for better mobility and reduced muscle tension.', '85751201', '85751201-Deep-Squat-Head-to-Floor-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Position yourself on the floor for Deep Squat Head To Floor. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'squat', 'Deep Squat Head To Floor', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a2cb12db-1714-4750-a33c-d5b3f7b79fae', 'Standing Overhead Press (Dumbbell) - Alternating', 'Shoulders', 'Dumbbells', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'The Dumbbell Standing Alternate Overhead Press is a pressing exercise that targets your delts for shoulder development. The triceps assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. Using dumbbells requires more stabilization than barbell variations. Strong shoulders improve overhead strength and support nearly all upper body movements.', '101771201', '101771201-Dumbbell-Standing-Alternate-Overhead-Press-(femal.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Alternate Overhead Press. 2. Begin in a standing position with good posture. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Alternate between sides/arms/legs with each repetition. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, 'Standing', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 99, 7, 9, TRUE, FALSE, 'shoulder_press', 'Standing Overhead Press - Alternating', 'lateral_raise, front_raise, rear_delt', FALSE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('a2f79d58-9c02-48e1-9a2f-4327d92ba9e2', 'Elbow To Elbow', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'Target your chest with the Elbow To Elbow, an effective movement movement for upper body strength. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics.', '52811201', '52811201-Elbow-to-Elbow-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Set up in the starting position for Elbow To Elbow. 2. Execute the movement with proper form, focusing on your chest. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Elbow To Elbow', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a2ff933c-f0be-4ac6-9ba9-43ba6910a8f8', 'Seated Row (Chair) - Alternating', 'Back', 'Chair', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Seated Alternating Row On A Chair is a rowing exercise that builds thickness in your upper back. You''ll also feel your biceps, rear delts working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Back development is crucial for pulling strength and overall upper body function.', '91191201', '91191201-Sitting-Alternating-Row-on-a-Chair-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Alternate between sides/arms/legs with each repetition. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Row On A Chair - Alternating', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('a3130ef0-4f49-48ac-97d7-93775f47a580', 'Inversion Bench Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Inversion Bench Crunch, focusing on your abs. You''ll also feel your hip flexors working to support the movement. Core strength is foundational for athletic performance and injury prevention.', '98051201', '98051201-Inversion-Bench-Crunch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Inversion Bench Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a31d8b80-38a6-4851-84e2-5be94b499ab3', 'Squat Side Power Kick', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic squatting movement gets your heart rate up while developing explosive strength. You''ll also feel your glutes, hamstrings working to support the movement. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '46351201', '46351201-Squat-Side-Power-Kick_Plyometrics.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Perform the concentric (lifting) phase explosively with maximum effort. 5. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Squat Side Power Kick', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a33ca817-84a7-4b19-9782-c309fce455db', 'Eagle Arms', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Flexibility work like this enhances performance and prevents stiffness. Progress gradually by increasing resistance over time.', '61691201', '61691201-Eagle-Arms-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Move into the stretch position for Eagle Arms. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'arm_exercise', 'Eagle Arms', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a3579fb1-6a5e-4c1e-899e-467d5d43acbf', 'Kneeling Hip Flexor Transverse', 'Legs', 'Bodyweight', '{"Hip Flexors"}'::text[], '{}'::text[], 'Target your hip flexors with this movement stretch that helps restore range of motion. Kneeling helps eliminate lower body momentum from the movement. Include this in your routine for better mobility and reduced muscle tension.', '78631201', '78631201-Kneeling-Hip-Flexor-Transverse-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Move into the stretch position for Kneeling Hip Flexor Transverse. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_stretch', 'Kneeling Hip Flexor Transverse', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a362b68e-dc11-4fa5-910c-df19973d1461', 'Strict Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. The forearms assist throughout the movement, making this a well-rounded exercise. Dumbbells allow each arm to work independently, helping correct imbalances. Dedicated arm training builds both strength and muscular definition.', '59191201', '59191201-Dumbbell-Srtict-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:28.851102+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Strict Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'bicep_curl', 'Strict Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('a38d9831-9336-4e8a-9e71-b1c36900b66b', 'Seated Diagonal Knee Raise On Bench', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. Secondary activation of your hip flexors provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Building core stability helps with everything from heavy deadlifts to daily activities.', '78051201', '78051201-Seated-Diagonal-Knee-Raise-on-Bench_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Raise the weight in the prescribed direction for Seated Diagonal Knee Raise On Bench. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'leg_raise', 'Seated Diagonal Knee Raise On Bench', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a39ef7ac-5690-4b7f-8c19-26c6954e30f3', 'Single Arm Low Scapular Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Secondary activation of your biceps, rear delts provides additional muscle engagement. Cable resistance creates smooth, continuous muscle engagement. Back development is crucial for pulling strength and overall upper body function.', '65121201', '65121201-Cable-Single-Arm-Low-Scapular-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Set the cable pulley to the lowest position and attach your preferred handle. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'arm_exercise', 'Single Arm Low Scapular Row', 'bent_over_row, lat_pulldown, bicep_curl', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('a3a00ab6-b29c-4722-b21d-70e18df90111', 'Clap Push Up_plyometrics', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. Secondary activation of your triceps, front delts provides additional muscle engagement. No equipment needed—your body provides all the resistance. Chest strength improves pushing power for sports, daily tasks, and other lifts. This is a great exercise for all fitness levels with proper scaling.', '12731201', '12731201-Clap-Push-Up_Plyometrics_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Complete all reps with control before resting. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'push_up', 'Clap Push Up_plyometrics', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('a3a24a79-e330-4fe1-b704-a23da4c088b1', 'PVC External Rotation', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Build a stronger back with this rotation movement targeting your rotator cuff. A strong back improves posture, prevents injury, and balances pressing movements.', '46021201', '46021201-PVC-External-Rotation_Back.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Rotate your torso through the movement pattern for PVC External Rotation. 2. Control the rotation in both directions—avoid using momentum. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'external_rotation', 'PVC External Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a3b75bca-60df-4251-8430-afcf9c1aa69b', 'Squat Hold', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Use this stretch to open up your quads area and enhance overall flexibility. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Include this in your routine for better mobility and reduced muscle tension. Can be modified for beginners or progressed for advanced athletes.', '77931201', '77931201-Bodyweight-Squat-Hold-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Hold the position for the prescribed time, maintaining tension. Ensure full range of motion on each rep.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'squat', 'Squat Hold', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('a3c02946-a1b5-48da-8cf0-03d6f6e46b2a', 'Jack Knife Sit Up', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. You''ll also feel your hip flexors working to support the movement. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '107121201', '107121201-Jack-knife-Sit-up-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Set up in the starting position for Jack Knife Sit Up. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'crunch', 'Jack Knife Sit Up', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('a3cd767e-35d6-44b6-a61a-4f50b5555aee', 'Decline Chest Fly - Single Arm (Cable)', 'Chest', 'Cables', '{"Chest","Lower Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'The Cable One Arm Decline Chest Fly is a flying exercise that targets your chest muscles. Your front delts work as secondary movers, adding to the training stimulus. Declining shifts the emphasis to hit the muscles from a different angle. Cables provide constant tension throughout the full range of motion. A well-developed chest contributes to upper body strength and aesthetics.', '12621201', '12621201-Cable-One-Arm-Decline-Chest-Fly_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Decline Chest Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', 'Fly', 'Pull', NULL, 'Unilateral', NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'decline_press', 'Single Arm Decline Chest Fly', 'squat, bench_press, deadlift', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('a3d1ee86-beb6-4e84-b8df-8e9c83ac3371', 'Lying Underhand Row On Rack - Close Grip (Barbell)', 'Back', 'Barbell, Flat Bench', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Barbell Lying Close Grip Underhand Row On Rack is a rowing exercise that builds thickness in your upper back. Your biceps, rear delts work as secondary movers, adding to the training stimulus. Performing this lying down removes momentum for stricter form. The barbell allows you to handle heavier loads for maximum strength gains. Back development is crucial for pulling strength and overall upper body function.', '44231201', '44231201-Barbell-Lying-Close-Grip-Underhand-Row-on-Rack_Bac.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Lying Close Grip Underhand Row On Rack. 2. Lie down in the appropriate position for Barbell Lying Close Grip Underhand Row On Rack. 3. Use a close/narrow grip (hands closer than shoulder-width). 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, 'Lying', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'general_exercise', 'Lying Underhand Row On Rack - Close Grip', 'Lying Underhand Row On Rack - Close Grip', FALSE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('a3e5bf49-6814-420e-a9f6-738ce9ce2537', 'Wrist Radial Deviation With Elbow Support', 'Arms', 'Bodyweight', '{"Forearms"}'::text[], '{}'::text[], 'Build grip strength and forearm size with this movement exercise. No equipment needed—your body provides all the resistance. Dedicated arm training builds both strength and muscular definition.', '84691201', '84691201-Bodyweight-Wrist-Radial-Deviation-with-Elbow-Suppo.mp4', 'female', FALSE, '2025-12-03 23:26:31.60311+00', '1. Set up in the starting position for Bodyweight Wrist Radial Deviation With Elbow Suppo. 2. Execute the movement with proper form, focusing on your forearms. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 40, 5, 7, FALSE, TRUE, 'general_exercise', 'Wrist Radial Deviation With Elbow Support', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a3e72214-4499-4075-b5db-1bad7c2d8a3f', 'Hip Circle Rotation', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Build leg strength with this rotation movement focusing on your delts. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '90621201', '90621201-Hip-Circle-Rotation-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Rotate your torso through the movement pattern for Hip Circle Rotation. 2. Control the rotation in both directions—avoid using momentum. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_circle', 'Hip Circle Rotation', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a3e78821-ad06-4d46-a0b0-225bdb1c6560', 'Tree Yoga Pose Open Chest', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Designed to lengthen your chest, the Tree Yoga Pose Open Chest helps improve mobility and prevent stiffness. You''ll also feel your shoulders working to support the movement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '96711201', '96711201-Tree-Yoga-Pose-Open-Chest-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Move into the stretch position for Tree Yoga Pose Open Chest. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Tree Yoga Pose Open Chest', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a3e81864-f81c-4964-8190-e6a22ea80436', 'Lying Frog Pulse', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this movement movement focusing on your core. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '69711201', '69711201-Lying-Frog-Pulse-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Frog Pulse. 2. At the bottom or top, pulse up and down in small movements before completing the rep. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'pulse', 'Lying Frog Pulse', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a40358c3-c0bd-4f6c-a449-351372e98d9a', 'Incline Skull Crusher (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This movement movement isolates your triceps for improved arm development. The incline angle shifts emphasis toward the upper portion of the target muscles. Cables provide constant tension throughout the full range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '43511201', '43511201-Cable-Incline-Skull-Crusher_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Adjust the cable machine to the correct height and attachment for Cable Incline Skull Crusher. 2. Set up in the starting position for Cable Incline Skull Crusher. 3. Execute the movement with proper form, focusing on your triceps. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 93, 7, 8, TRUE, TRUE, 'tricep_extension', 'Incline Skull Crusher', 'tricep_pushdown, close_grip_bench', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('a4062998-271b-488c-9991-28922a4e10f0', 'Planche Dip On Parallel Bars (Dip Bars)', 'Chest', 'Dip Bars', '{"Lower Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This dipping exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your triceps, front delts, core working to support the movement. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '74151201', '74151201-Planche-Dip-on-Parallel-Bars-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Lower your body by bending your elbows to about 90 degrees. 2. Push back up until your arms are fully extended. 3. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 5, 7, 8, TRUE, TRUE, 'dip', 'Planche Dip On Parallel Bars', 'bench_press, tricep_pushdown, push_up', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a4138da0-f36c-400b-a962-fe346b380ab7', 'Seated Elbow Chest Fly (Chair)', 'Chest', 'Chair', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Seated Elbow Chest Fly On A Chair is a flying exercise that targets your chest muscles. The front delts assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. A well-developed chest contributes to upper body strength and aesthetics.', '86161201', '86161201-Seated-Elbow-Chest-Fly-on-a-Chair-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. With a slight bend in your elbows, move the weight in a wide arc. 4. Squeeze your chest muscles at the center/top of the movement. 5. Return with control, feeling the stretch at the bottom. 6. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 67, 5, 7, FALSE, TRUE, 'chest_fly', 'Seated Elbow Chest Fly On A Chair', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a4353d6c-ba0b-456b-b400-a973a301a90d', 'Incline Hammer Curl (Dumbbell) - Alternating', 'Arms', 'Dumbbells, Incline Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Dumbbell Incline Alternate Hammer Curl is a curling exercise that isolates your biceps. You''ll also feel your forearms working to support the movement. The incline angle shifts emphasis toward the upper portion of the target muscles. Using dumbbells requires more stabilization than barbell variations. Dedicated arm training builds both strength and muscular definition.', '12331201', '12331201-Dumbbell-Incline-Alternate-Hammer-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Alternate Hammer Curl. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 95, 5, 7, FALSE, TRUE, 'hammer_curl', 'Incline Hammer Curl - Alternating', 'bicep_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('a438f0fc-a16e-4868-9cf6-524266df54bc', 'Brettzel', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your full body, the Brettzel helps improve mobility and prevent stiffness. Include this in your routine for better mobility and reduced muscle tension.', '75391201', '75391201-Brettzel-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Move into the stretch position for Brettzel. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Brettzel', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a43ead37-d45a-4664-a427-dda87d5c50d0', 'Weighted Russian Twist (Kettlebell)', 'Core', 'Kettlebell', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Kettlebell Weighted Russian Twist targets your obliques through a twisting motion, building rotational core strength. Your abs work as secondary movers, adding to the training stimulus. Kettlebells are excellent for building functional, real-world strength. Building core stability helps with everything from heavy deadlifts to daily activities.', '83711201', '83711201-Kettlebell-Weighted-Russian-Twist-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Select an appropriately weighted kettlebell for Kettlebell Weighted Russian Twist. 2. Rotate your torso through the movement pattern for Kettlebell Weighted Russian Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 58, 5, 7, FALSE, TRUE, 'russian_twist', 'Weighted Russian Twist', 'crunch, plank, leg_raise, wood_chop', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('a459595e-ddf5-4df1-8b05-b2f4fa06bc14', 'Single Leg Star Balance', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '42121201', '42121201-One-Leg-Star-Balance_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Complete all reps on one side, then switch to the other side. 2. Set up in the starting position for One Leg Star Balance. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'balance', 'Single Leg Star Balance', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a45c8265-94a6-4d56-be3c-8c80f7f993ec', 'Single Leg Stand', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities. Aim for full range of motion on every rep.', '106781201', '106781201-Single-Leg-Stand-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Complete all reps on one side, then switch to the other side. 2. Set up in the starting position for Single Leg Stand. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'leg_exercise', 'Single Leg Stand', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a469d736-491e-419f-a4c4-9d63e6917e22', 'Bent Over Row (Dumbbell)', 'Back', 'Dumbbells', '{"Back","Lats"}'::text[], '{"Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Your biceps, lats work as secondary movers, adding to the training stimulus. The bent over position requires core engagement to maintain a neutral spine. The dumbbell variation provides freedom of movement and greater range of motion. Back development is crucial for pulling strength and overall upper body function.', '24821201', '24821201-Dumbbell-Bent-Over-Row-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Bent Over Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'bent_over_row', 'Bent Over Row', 'cable_row, dumbbell_row, t_bar_row, lat_pulldown', FALSE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('a46a0f48-4078-4f4a-9cca-9eb955172e4a', 'Single Leg Glute Bridge - Alternating', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Alternate Single Leg Glute Bridge is a hip-dominant bridging exercise that targets your glutes. Your hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '74321201', '74321201-Alternate-Single-Leg-Glute-Bridge-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Alternate between sides/arms/legs with each repetition. 5. Repeat for the prescribed number of repetitions. Keep your core engaged for stability. This variation specifically emphasizes the glutes.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'glute_bridge', 'Single Leg Glute Bridge - Alternating', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a470b505-8b26-4a8a-ae57-e118afdb0f65', 'Front Toe Touching', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. The hip flexors assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention. Perfect for including in both strength and hypertrophy programs.', '32481201', '32481201-Front-Toe-Touching-(female).mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Set up in the starting position for Front Toe Touching. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'toe_touch', 'Front Toe Touching', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a475b2b8-755c-4871-87b2-c176a12f3f11', 'Lying Butt Curl', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Lying Butt Curl is a lower body curling exercise that targets your biceps. Your forearms work as secondary movers, adding to the training stimulus. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '64121201', '64121201-Lying-Butt-Curl-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Butt Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'general_exercise', 'Lying Butt Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a47d14cd-acb8-49fd-8c36-eb377afb5f7f', 'Side Lunge (Resistance Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Bands are joint-friendly and portable, perfect for any training environment. Leg training boosts metabolism and builds functional, real-world strength.', '72021201', '72021201-Resistance-Band-Side-Lunge-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Side Lunge. 2. Step to the side, bending that knee while keeping the other leg straight. 3. Push through your front/working leg to return to the starting position. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'lunge', 'Side Lunge', 'split_squat, step_up, squat', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('a48a892f-0a67-4392-93bd-30cc98ab9869', 'Toe Walk (Resistance Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This stepping movement focuses on your gastrocnemius and soleus. Bands are joint-friendly and portable, perfect for any training environment. Strong legs are the foundation for athletic performance and functional fitness.', '107601201', '107601201-Resistance-Band-Toe-Walk_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Secure the resistance band appropriately for Resistance Band Toe Walk. 2. Set up in the starting position for Resistance Band Toe Walk. 3. Execute the movement with proper form, focusing on your calves. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'walking', 'Toe Walk', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('a48d102b-e559-41d0-ba80-b6778b50a9c0', 'Jack Step', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic stepping movement gets your heart rate up while developing explosive strength. The quads assist throughout the movement, making this a well-rounded exercise. Great for improving athletic performance, burning calories, and building conditioning.', '54861201', '54861201-Jack-Step-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Jack Step. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Jack Step', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('a48d8ebd-13e3-41ad-a95e-0df521f1758d', 'Standing 5 Arm Cross And Elbow Lift - Alternating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This full-body movement exercise challenges multiple muscle groups simultaneously. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Full body exercises are time-efficient and build functional, real-world strength.', '94711201', '94711201-Standing-Alternating-5-Arm-Cross-And-Elbow-Lift-(f.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Begin in a standing position with good posture. 2. Alternate between sides/arms/legs with each repetition. 3. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'boxing', 'Standing 5 Arm Cross And Elbow Lift - Alternating', 'shoulder_press, lateral_raise, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a4954818-2bf8-4e28-909e-d7bcf7b25514', 'Lying Floor Svend Press', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Lying Floor Svend Press is a pressing exercise that targets your chest muscles. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '105501201', '105501201-Lying-Floor-Svend-Press-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Position yourself on the floor for Lying Floor Svend Press. 2. Lie down in the appropriate position for Lying Floor Svend Press. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'squeeze_press', 'Lying Floor Svend Press', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a4a31d2c-f459-4a5d-9e53-87b5addb2973', 'Leg Extension (Plate Loaded Machine)', 'Legs', 'Leg Extension Machine', '{"Quads"}'::text[], '{}'::text[], 'This extension movement emphasizes your quadriceps for stronger, more powerful legs. The fixed path allows you to focus purely on muscular effort. Leg training boosts metabolism and builds functional, real-world strength.', '18731201', '18731201-Lever-Leg-Extension-(Plate-Loaded)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Leg Extension. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'leg_extension', 'Lever Leg Extension', 'squat, leg_press, lunge', TRUE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('a4af61f0-daaf-4bc6-b2cd-877f9dc210b9', 'Lateral Step And Squat (Resistance Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes, hamstrings provides additional muscle engagement. The band creates increasing tension as it stretches, challenging the lockout. Leg training boosts metabolism and builds functional, real-world strength.', '72061201', '72061201-Resistance-Band-Lateral-Step-and-Squat-(female)_Hi.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Lateral Step And Squat. 2. Set up a box or step platform at the appropriate height. 3. Push your hips back and bend your knees to lower your body. 4. Keep your chest up and knees tracking over your toes. 5. Drive through your heels to stand back up, squeezing your glutes at the top. 6. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'squat', 'Lateral Step And Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('a4cd66ba-a2e4-42c4-a742-8e10eb85be86', 'Flutter (Chair)', 'Core', 'Chair', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this movement movement focusing on your abs. Secondary activation of your hip flexors provides additional muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '76651201', '76651201-Flutter-on-a-Chair-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Set up in the starting position for Flutter On A Chair. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'general_exercise', 'Flutter On A Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a4cf4ae1-af67-4869-a462-adeb2005c6de', 'Lying Back Contraction', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger back with this movement movement targeting your core. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Back development is crucial for pulling strength and overall upper body function. Control the negative portion for maximum muscle engagement.', '82291201', '82291201-Lying-Back-Contraction-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Back Contraction. 2. Set up in the starting position for Lying Back Contraction. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Lying Back Contraction', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a4d9b639-16d9-4dc3-956a-cd3a97e70678', 'Standing Balance Single Leg Lifts', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Standing Balance Single Leg Lifts is a lower body movement exercise that targets your full body. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '88631201', '88631201-Standing-Balance-Single-Leg-Lifts-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand with feet about shoulder-width apart. 2. Complete all reps on one side, then switch to the other side. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 47, 7, 8, TRUE, TRUE, 'balance', 'Standing Balance Single Leg Lifts', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a4e178f1-86f5-418e-a101-d4a6dc4a4937', 'Front Squat Arms Crossed (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Core"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Barbells enable bilateral loading for building raw strength. Strong legs are the foundation for athletic performance and functional fitness.', '25021201', '25021201-Barbell-Front-Squat-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Front Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', 'Squat', 'Push', 'Compound', 'Bilateral', NULL, 4, NULL, 10, 10, NULL, 4, 'Standing', NULL, 'Overhand', 'Standard (Shoulder-Width)', 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 89, 7, 9, TRUE, FALSE, 'front_squat', 'Front Squat', 'squat, leg_press, leg_extension, goblet_squat', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('a4e5c7db-054d-4b36-971c-341635b496b7', 'Pushdown Rope (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This pushing movement isolates your triceps for improved arm development. The cable setup allows you to adjust the angle of resistance. Arm strength supports grip, pulling, and pushing in compound movements. Aim for full range of motion on every rep.', '24381201', '24381201-Cable-Pushdown-(with-rope-attachment)-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Pushdown. 2. Set up in the starting position for Cable Pushdown. 3. Execute the movement with proper form, focusing on your triceps. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'tricep_pushdown', 'Pushdown', 'tricep_extension, close_grip_bench, dip', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('a4f3a0a6-7cb7-4651-8668-56fd4212aa2f', 'Swing - Overhand Grip (Kettlebell)', 'Arms', 'Kettlebell', '{"Forearms"}'::text[], '{}'::text[], 'Develop functional strength with the Kettlebell Overhand Grip Swing, a comprehensive swinging exercise. Your glutes, core work as secondary movers, adding to the training stimulus. Kettlebells are excellent for building functional, real-world strength. Compound movements like this develop coordination, power, and overall fitness.', '36801201', '36801201-Kettlebell-Overhand-Grip-Swing-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Select an appropriately weighted kettlebell for Kettlebell Overhand Grip Swing. 2. Use an overhand (pronated) grip with palms facing down/away. 3. Hinge at your hips, letting the weight swing back between your legs. 4. Explosively drive hips forward, propelling the weight forward/up. 5. Let gravity bring it back as you hinge for the next rep. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'general_exercise', 'Swing - Overhand Grip', 'Swing - Overhand Grip', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('a5019d23-edf1-402c-b84f-cde6e995b055', 'Lying T Bar Row (Machine)', 'Back', 'Row Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Your biceps, lats work as secondary movers, adding to the training stimulus. Performing this lying down removes momentum for stricter form. Machine exercises are great for isolating muscles and training to failure safely. Back development is crucial for pulling strength and overall upper body function.', '11941201', '11941201-Lever-Lying-T-bar-Row_Back.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Lying T Bar Row. 2. Lie down in the appropriate position for Lever Lying T Bar Row. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, 'Lying', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 78, 7, 9, TRUE, FALSE, 't_bar_row', 'Lever Lying T Bar Row', 'bent_over_row, lat_pulldown, deadlift', FALSE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('a5050a6e-10f9-438a-a1e5-88b9c3d6672f', 'Standing Scapular External Rotation (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Build a stronger back with this rotation movement targeting your rotator cuff. Performing this standing challenges your balance and core engagement. Using dumbbells requires more stabilization than barbell variations. A strong back improves posture, prevents injury, and balances pressing movements.', '72341201', '72341201-Dumbbell-Standing-Scapular-External-Rotation-(back-POV)-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Scapular External Rotation. 2. Stand tall with your feet firmly planted. 3. Rotate your torso through the movement pattern for Dumbbell Standing Scapular External Rotation. 4. Control the rotation in both directions—avoid using momentum. 5. Complete all reps with control before resting. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 46, 7, 8, TRUE, TRUE, 'external_rotation', 'Standing Scapular External Rotation', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('a5055df8-54bb-49fd-b1b0-8418d31e67f1', 'Hamstring Stretch (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'The Hamstring Stretch targets your hamstrings through a controlled stretching motion. Leg training boosts metabolism and builds functional, real-world strength.', '42851201', '42851201-Hamstring-Stretch-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Set up in the starting position for Hamstring Stretch. 2. Execute the movement with proper form, focusing on your hamstrings. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 28, 2, 6, FALSE, TRUE, 'hamstring_stretch', 'Hamstring Stretch', 'stretch_hip, stretch_calf, stretch_back', FALSE, 'gymnastic_rings', TRUE, 1, 30, 2, 68, 85, 85, 70),
('a50c1248-1372-4921-a6b0-0909a40aa361', 'Box Drop Split Stance Land', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. Develops fast-twitch muscle fibers for quicker, more powerful movements. Works well as both a primary exercise or accessory movement.', '90711201', '90711201-Box-Drop-Split-Stance-Land-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Box Drop Split Stance Land. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'box_jump', 'Box Drop Split Stance Land', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a51775fa-37f1-4b77-85f2-9937cdb7117d', 'Assisted Single Arm Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. You''ll also feel your biceps, upper back working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Back development is crucial for pulling strength and overall upper body function.', '69541201', '69541201-Assisted-Single-Arm-Pull-up-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Complete all reps on one side, then switch to the other side. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'pull_up', 'Assisted Single Arm Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a5210c89-82a7-4f9b-be6a-58c0270a1a85', 'Bent Over Single Arm Row (Dumbbell)', 'Back', 'Dumbbells', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Dumbbell Bent Over Single Arm Row is a rowing exercise that builds thickness in your upper back. Your biceps, rear delts work as secondary movers, adding to the training stimulus. The bent over position requires core engagement to maintain a neutral spine. The dumbbell variation provides freedom of movement and greater range of motion. Back development is crucial for pulling strength and overall upper body function.', '91831201', '91831201-Dumbbell-Bent-Over-Single-Arm-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps on one side, then switch to the other side. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 77, 7, 9, TRUE, FALSE, 'dumbbell_row', 'Bent Over Single Arm Row', 'bent_over_row, lat_pulldown, bicep_curl', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('a5243f94-f3eb-4d3d-a13c-26c93e584c8d', 'Push Press', 'Shoulders', 'Bodyweight', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'The Push Press is a pressing exercise that targets your delts for shoulder development. This bodyweight exercise requires no equipment and can be done anywhere. Strong shoulders improve overhead strength and support nearly all upper body movements.', '12001201', '12001201-Push-Press_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Start with the weight at shoulder level. 2. Press directly overhead until your arms are fully extended. 3. Lower back to shoulder level with control. 4. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Push Press', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a52e54eb-4779-446d-87d1-c619edc2a3f2', 'Kneeling Rotation Torso Thread Through', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Kneeling Rotation Torso Thread Through is a flexibility exercise that targets your core, helping to release tension and improve range of motion. Kneeling helps eliminate lower body momentum from the movement. Flexibility work like this enhances performance and prevents stiffness.', '81541201', '81541201-Kneeling-Rotation-Torso-Thread-Through-(female)_St.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Rotate your torso through the movement pattern for Kneeling Rotation Torso Thread Through. 3. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Kneeling Rotation Torso Thread Through', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a52ff5a1-8c2a-4270-89fc-a93da5b100a4', 'Dynamic Splits Side Bend Yoga Pose', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Target your obliques with this movement stretch that helps restore range of motion. The abs assist throughout the movement, making this a well-rounded exercise. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '97631201', '97631201-Dynamic-Splits-Side-Bend-Yoga-Pose-(female)_Stretc.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Move into the stretch position for Dynamic Splits Side Bend Yoga Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'side_bend', 'Dynamic Splits Side Bend Yoga Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a532ca10-1e3b-4d8b-b1f8-99150447b904', 'Drag Curl (Barbell)', 'Arms', 'Barbell', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Your forearms work as secondary movers, adding to the training stimulus. Barbells enable bilateral loading for building raw strength. Dedicated arm training builds both strength and muscular definition.', '381201', '00381201-Barbell-Drag-Curl_Upper-Arms-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Grip a barbell with hands at the appropriate width for Barbell Drag Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', 'Isolation', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, 'Underhand (Supinated)', 'Standard', 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'bicep_curl', 'Drag Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('a53753bf-9f3f-4b49-b7e8-281e6f654b6b', 'Single Russian Twist', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Elevate your training with this twisting exercise that develops speed, power, and coordination. Secondary activation of your abs provides additional muscle engagement. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '91581201', '91581201-Single-Russian-Twist-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Rotate your torso through the movement pattern for Single Russian Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Single Russian Twist', 'crunch, plank, leg_raise, wood_chop', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a53a0e47-193e-409a-a46e-47833bfe0c25', 'Plank Jack On Elbows', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build power and athleticism with this high-intensity stabilization exercise that challenges your entire body. Your shoulders, lower back work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '71701201', '71701201-Plank-Jack-on-Elbows-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears. An effective movement for your plyometrics routine.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'plank', 'Plank Jack On Elbows', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('a53b585a-234b-4426-850e-09212296da30', 'Ab Twist Toe Tap', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. Your abs work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '84021201', '84021201-Ab-Twist-Toe-Tap-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Rotate your torso through the movement pattern for Ab Twist Toe Tap. 2. Control the rotation in both directions—avoid using momentum. 3. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', 'Trunk Rotation + Hip Flexion (Toe Tap)', 'Static', 'Compound', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Ab Twist Toe Tap', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a5416906-0e69-4755-b348-9f459a24b2aa', '21s (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This movement exercise focuses on your biceps for improved arm size and strength. Your forearms work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Dedicated arm training builds both strength and muscular definition.', '54691201', '54691201-Dumbbell-21s_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell 21s. 2. Set up in the starting position for Dumbbell 21s. 3. Execute the movement with proper form, focusing on your biceps. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'general_exercise', '21s', 'tricep_extension, hammer_curl', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('a5468fc5-357c-454c-b7a9-670871d3d24a', 'Shrug (Machine)', 'Back', 'Shrug Machine', '{"Traps"}'::text[], '{"Upper Back"}'::text[], 'Build a stronger back with this shrugging movement targeting your traps. The machine guides your movement path for safer, more controlled repetitions. Back development is crucial for pulling strength and overall upper body function. Maintain proper breathing - exhale during the effort phase.', '6041201', '06041201-Lever-Shrug-(plate-loaded)_Back.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Shrug. 2. Shrug your shoulders straight up toward your ears. 3. Hold briefly at the top, then lower with control. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'shrug', 'Lever Shrug', 'deadlift, bent_over_row, face_pull', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('a54bf54a-d23e-4add-a240-b03ef22365e1', 'Back Extension (Machine)', 'Back', 'Lever Machine', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This extension exercise engages your abs for improved core stability and strength. Your glutes work as secondary movers, adding to the training stimulus. Machine exercises are great for isolating muscles and training to failure safely. Core strength is foundational for athletic performance and injury prevention.', '5731201', '05731201-Lever-Back-Extension_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Back Extension. 2. Raise your torso by extending at the lower back/hips. 3. Lower with control, maintaining tension. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'back_extension', 'Lever Back Extension', 'good_morning, bird_dog, superman', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('a5623ff9-f0e1-4792-8d19-2f19e69865a0', 'External Rotation (TRX)', 'Shoulders', 'TRX', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Build a stronger back with this rotation movement targeting your rotator cuff. Suspension training adds instability, increasing core activation throughout. A strong back improves posture, prevents injury, and balances pressing movements.', '75071201', '75071201-Suspender-External-Rotation_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender External Rotation. 2. Rotate your torso through the movement pattern for Suspender External Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'external_rotation', 'Suspender External Rotation', 'squat, bench_press, deadlift', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('a56a64b9-371b-4e04-9b99-fcbfb86b0c51', 'Seated Curl (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Dumbbell Seated Curl is a curling exercise that isolates your biceps. Secondary activation of your forearms provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. The dumbbell variation provides freedom of movement and greater range of motion. Dedicated arm training builds both strength and muscular definition.', '3911201', '03911201-Dumbbell-Seated-Curl_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Curl. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'leg_curl', 'Seated Curl', 'romanian_deadlift, hip_thrust', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('a56da280-ae92-4652-9aea-8af784bb1779', 'Seated Bent Over Back Stretch', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'The Seated Bent Over Back Stretch is a flexibility exercise that targets your back, helping to release tension and improve range of motion. Being seated provides stability, allowing you to focus on the working muscles. Flexibility work like this enhances performance and prevents stiffness.', '43111201', '43111201-Sitting-Bent-Over-Back-Stretch-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Bent Over Back Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'back_stretch', 'Seated Bent Over Back Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a573b224-c7a5-4667-b6ed-ac6ca40dea0c', 'Overhead Lunge (Kettlebell)', 'Legs', 'Kettlebell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Kettlebells are excellent for building functional, real-world strength. Strong legs are the foundation for athletic performance and functional fitness.', '65211201', '65211201-Kettlebell-Overhead-Lunge_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Select an appropriately weighted kettlebell for Kettlebell Overhead Lunge. 2. Step forward into a lunge until both knees are at about 90 degrees. 3. Push through your front/working leg to return to the starting position. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'lunge', 'Overhead Lunge', 'split_squat, step_up, squat', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('a574cc64-c9c4-4f60-bac3-80e23041de6c', 'Lying External Shoulder Rotation (Dumbbell)', 'Shoulders', 'Dumbbells, Flat Bench', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Target your rotator cuff with the Dumbbell Lying External Shoulder Rotation, an effective shoulder rotation exercise. Performing this lying down removes momentum for stricter form. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '30791201', '30791201-Dumbbell-Lying-External-Shoulder-Rotation-(female).mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying External Shoulder Rotation. 2. Lie down in the appropriate position for Dumbbell Lying External Shoulder Rotation. 3. Rotate your torso through the movement pattern for Dumbbell Lying External Shoulder Rotation. 4. Control the rotation in both directions—avoid using momentum. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Lying External Shoulder Rotation', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('a5780492-5fb0-4a0d-a8f2-1a62062f6e65', 'Half Happy Baby', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your hips, the Half Happy Baby helps improve mobility and prevent stiffness. Your lower back, adductors work as secondary movers, adding to the training stimulus. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '82091201', '82091201-Half-Happy-Baby-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Move into the stretch position for Half Happy Baby. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 15, 7, 8, TRUE, TRUE, 'yoga', 'Half Happy Baby', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a579b31a-e87c-42b1-9e0c-97ed95b8db09', 'V Up With Clap', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The V Up With Clap is a core movement exercise that primarily targets your abs. You''ll also feel your hip flexors working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '42711201', '42711201-V-up-with-Clap-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Set up in the starting position for V Up With Clap. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'v_up', 'V Up With Clap', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a5823893-5190-43b6-bf21-7c312076716b', 'Chest Press (Machine)', 'Chest', 'Chest Press Machine', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Lever Chest Press, an effective pressing movement for upper body strength. You''ll also feel your triceps, front delts working to support the movement. The machine guides your movement path for safer, more controlled repetitions. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '70821201', '70821201-Lever-Chest-Press-(VERSION-3)-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Chest Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps with control before resting. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'bench_press', 'Lever Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('a5826cdf-0073-4d2e-880d-846d42c5bf86', 'Single Leg Calf Raise (Dumbbell)', 'Legs', 'Dumbbells', '{"Calves"}'::text[], '{}'::text[], 'This raising movement focuses on your gastrocnemius and soleus. Dumbbells allow each arm to work independently, helping correct imbalances. Strong legs are the foundation for athletic performance and functional fitness.', '4091201', '04091201-Dumbbell-Single-Leg-Calf-Raise_Calves.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Lower your heels below the platform to get a full stretch. 3. Rise up onto your toes as high as possible, squeezing your calves. 4. Lower with control and repeat. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 87, 5, 7, FALSE, TRUE, 'calf_raise', 'Single Leg Calf Raise', 'standing_calf_raise, seated_calf_raise, tibialis_raise', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('a5988143-177a-43fd-9189-8b27e1ca58e3', 'Lying Upper Body Superman Row', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Upper Back"}'::text[], 'The Lying Upper Body Superman Row is a rowing exercise that builds thickness in your upper back. Secondary activation of your glutes provides additional muscle engagement. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. A strong back improves posture, prevents injury, and balances pressing movements.', '95491201', '95491201-Lying-Upper-Body-Superman-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Upper Body Superman Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'back_extension', 'Lying Upper Body Superman Row', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a5997588-9afe-4cab-83cf-8c056638d2b8', 'Seated March (Chair)', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. Your hip flexors work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Great for improving athletic performance, burning calories, and building conditioning.', '69071201', '69071201-Sitting-March-on-a-Chair-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting. Exhale during the exertion phase of the movement. Perfect for targeting your full body.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'marching', 'Seated March On A Chair', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a599d738-6f55-4000-97bf-8aa70b6151ca', 'Overhead Full Sumo Squat Stretch (Stick)', 'Legs', 'Bodyweight', '{"Neck"}'::text[], '{"Glutes","Inner Thighs","Hamstrings"}'::text[], 'The Stick Overhead Full Sumo Squat Stretch provides a deep stretch for your full body, ideal for recovery and mobility work. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '54071201', '54071201-Stick-Overhead-Full-Sumo-Squat-Stretch-(female)_Hi.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. Maintain a neutral spine throughout. An effective movement for your stretching routine.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 75, 2, 6, FALSE, TRUE, 'neck_stretch', 'Stick Overhead Full Sumo Squat Stretch', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a59e8aa4-7e45-45fb-8d98-1ead4008f6b5', 'Swing', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Glutes","Core"}'::text[], 'Develop functional strength with the Bodyweight Swing, a comprehensive swinging exercise. You''ll also feel your glutes, core working to support the movement. A versatile bodyweight movement perfect for home or gym training. Full body exercises are time-efficient and build functional, real-world strength.', '58641201', '58641201-Bodyweight-Swing_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Hinge at your hips, letting the weight swing back between your legs. 2. Explosively drive hips forward, propelling the weight forward/up. 3. Let gravity bring it back as you hinge for the next rep. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Swing', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a5b7276e-0148-4ab5-95d1-5f266c444558', 'Hook Kick Kickboxing (with Boxing Bag)', 'Full Body', 'Bodyweight', '{"Shoulders"}'::text[], '{"Biceps","Triceps","Core"}'::text[], 'The Hook Kick Kickboxing (with Boxing Bag) is an explosive exercise that combines cardiovascular training with dynamic kicking movements. You''ll also feel your shoulders, core working to support the movement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '45881201', '45881201-Hook-Kick-Kickboxing-(with-boxing-bag)_Plyometrics.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Hook Kick Kickboxing. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Hook Kick Kickboxing', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a5bf1375-37ec-4648-8433-0b430492a11c', 'Incline Push Up (Chair)', 'Chest', 'Chair', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your triceps, front delts working to support the movement. The incline angle shifts emphasis toward the upper portion of the target muscles. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '71341201', '71341201-Incline-Push-up-with-Chair_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'push_up', 'Incline Push Up With Chair', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a5cfcc02-0892-42b0-866b-5ed76260b2d7', 'Seated Row (Resistance Band)', 'Back', 'Resistance Band, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Resistance Band Seated Row is a rowing exercise that builds thickness in your upper back. The biceps, lats assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. The band creates increasing tension as it stretches, challenging the lockout. Back development is crucial for pulling strength and overall upper body function.', '83561201', '83561201-Resistance-Band-Seated-Row-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Secure the resistance band appropriately for Resistance Band Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 87, 7, 8, TRUE, TRUE, 'cable_row', 'Seated Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('a5f78e7f-d1c9-409e-933c-0ff204721d86', 'Revolved Head To Knee Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Revolved Head To Knee Pose provides a deep stretch for your full body, ideal for recovery and mobility work. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '59081201', '59081201-Revolved-Head-to-Knee-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Move into the stretch position for Revolved Head To Knee Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'yoga', 'Revolved Head To Knee Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a5ff8b8c-1570-456c-b00e-f4f09cfb91a6', 'Lying Fly (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This flying exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your front delts working to support the movement. The lying position provides back support and helps isolate the target muscles. Cables provide constant tension throughout the full range of motion. A well-developed chest contributes to upper body strength and aesthetics.', '24261201', '24261201-Cable-Lying-Fly-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Lying Fly. 2. Lie down in the appropriate position for Cable Lying Fly. 3. With a slight bend in your elbows, move the weight in a wide arc. 4. Squeeze your chest muscles at the center/top of the movement. 5. Return with control, feeling the stretch at the bottom. 6. Complete all reps with control before resting. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'chest_fly', 'Lying Fly', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('a6074361-9bdc-4847-84f2-1e00311149da', 'Incline Bench Press (Smith Machine)', 'Chest', 'Smith Machine, Flat Bench', '{Pectorals}'::text[], '{"Front Delts","Triceps"}'::text[], 'The Smith Incline Bench Press is a pressing exercise that targets your chest muscles. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. Using an incline changes the angle of resistance for varied muscle recruitment. The fixed path allows you to focus purely on muscular effort. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '7571201', '07571201-Smith-Incline-Bench-Press_Chest-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Incline Bench Press. 2. Set the bench to an incline angle (30-45 degrees). 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 96, 7, 9, TRUE, FALSE, 'incline_press', 'Smith Incline Bench Press', 'Incline Bench Press', FALSE, 'smith_machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('a62dfa18-9848-477a-b20b-cd0a505f7463', 'Bench Press On Floor - Reverse Grip (Barbell)', 'Chest', 'Barbell', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Barbell Reverse Grip Bench Press On Floor is a pressing exercise that targets your chest muscles. Secondary activation of your triceps, front delts provides additional muscle engagement. The barbell allows you to handle heavier loads for maximum strength gains. A well-developed chest contributes to upper body strength and aesthetics.', '67171201', '67171201-Barbell-Reverse-Grip-Bench-Press-on-Floor_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'bench_press', 'Bench Press On Floor - Reverse Grip', 'Bench Press On Floor - Reverse Grip', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('a641c16b-d1cc-4b7b-beff-305b8b06f36b', 'Fly Front Step', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Fly Front Step is an explosive exercise that combines cardiovascular training with dynamic flying movements. Your quads work as secondary movers, adding to the training stimulus. Plyometric training builds explosive power that transfers to sports and daily activities.', '69271201', '69271201-Fly-Front Step-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Set up a box or step platform at the appropriate height. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'general_exercise', 'Fly Front Step', 'bench_press, incline_bench_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a654d713-9052-4d6c-8d2b-b4c0a0354ef0', 'Major Muscles Groups White', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Major Muscles Groups White is a compound movement exercise that engages your entire body. This bodyweight exercise requires no equipment and can be done anywhere. Full body exercises are time-efficient and build functional, real-world strength.', '12511201', '12511201-Major-Muscles-Groups-WHITE.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Set up in the starting position for Major Muscles Groups White. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Major Muscles Groups White', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a657a67e-595a-455e-9959-b319891a5b94', 'Sumo Deadlift (Smith Machine)', 'Legs', 'Smith Machine', '{"Glutes"}'::text[], '{"Quads","Lower Back","Inner Thighs"}'::text[], 'The Smith Sumo Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. Secondary activation of your glutes, lower back provides additional muscle engagement. The fixed path allows you to focus purely on muscular effort. Lower body strength improves everything from walking to heavy compound lifts.', '73741201', '73741201-Smith-Sumo-Deadlift_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Sumo Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'deadlift', 'Smith Sumo Deadlift', 'Sumo Deadlift', FALSE, 'smith_machine', FALSE, 4, 120, 6, 80, 75, 20, 88),
('a65cf473-26f6-476c-9776-996105dbc355', 'Side Bow Stretch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This stretching exercise engages your abs for improved core stability and strength. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '61721201', '61721201-Side-Bow-Stretch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Set up in the starting position for Side Bow Stretch. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Side Bow Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a65ea375-35af-4d92-8d13-fe030495aadf', 'Standing Arm Lift - Alternating', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Target your delts with the Standing Alternating Arm Lift, an effective shoulder movement exercise. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Strong shoulders improve overhead strength and support nearly all upper body movements.', '96191201', '96191201-Standing-Alternating-Arm-Lift-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Stand tall with your feet firmly planted. 2. Alternate between sides/arms/legs with each repetition. 3. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'arm_exercise', 'Standing Arm Lift - Alternating', 'shoulder_press, lateral_raise, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a6675db3-4019-4e92-8ae6-2f5a4142e8a8', 'Skipping Without Rope Marching On Spot', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. Secondary activation of your hip flexors provides additional muscle engagement. Plyometric training builds explosive power that transfers to sports and daily activities.', '88291201', '88291201-Skipping-without-Rope-Marching-on-Spot-(female)_Pl.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Set up in the starting position for Skipping Without Rope Marching On Spot. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'skip', 'Skipping Without Rope Marching On Spot', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('a6689957-4e16-4313-ade2-0a2e4acba6a4', 'Calf Press (Machine)', 'Legs', 'Calf Raise Machine', '{"Calves"}'::text[], '{}'::text[], 'The Lever Calf Press (plate Loaded) isolates your calf muscles through a pressing motion. The fixed path allows you to focus purely on muscular effort. Strong legs are the foundation for athletic performance and functional fitness.', '22891201', '22891201-Lever-Calf-Press-(Plate-Loaded)_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Calf Press. 2. Execute the pressing motion for Lever Calf Press, extending through the target muscles. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'calf_raise', 'Lever Calf Press', 'standing_calf_raise, seated_calf_raise, tibialis_raise', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('a67038e4-3814-473d-a77c-15e11c88bd09', 'Assisted Chin Up From Knee (Band)', 'Back', 'Resistance Band, Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This movement exercise emphasizes your lats for improved back development. Your biceps work as secondary movers, adding to the training stimulus. Bands are joint-friendly and portable, perfect for any training environment. A strong back improves posture, prevents injury, and balances pressing movements.', '42061201', '42061201-Band-Assisted-Chin-Up-(From-Knee)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Secure the resistance band appropriately for Band Assisted Chin Up. 2. Pull yourself up, focusing on bicep and lat engagement. 3. Raise until chin is over the bar, lower with full control. 4. Complete all reps with control before resting.', 'Vertical Pull', 'Pull', 'Compound', 'Bilateral', NULL, 2, NULL, 7, 7, NULL, 5, 'Hanging', NULL, 'Underhand (Supinated)', 'Standard', 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 67, 7, 8, TRUE, TRUE, 'pull_up', 'Assisted Chin Up', 'lat_pulldown, bent_over_row, bicep_curl', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('a68688c2-c565-45a4-8dd4-8280b37cd43e', 'Lying Butterfly (abduction) - Alternating', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Lying Alternate Butterfly (abduction) is a lower body flying exercise that targets your glute med/abductors. Secondary activation of your front delts provides additional muscle engagement. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '67021201', '67021201-Lying-Alternate-Butterfly-(Abduction)-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Lie down in the appropriate position for Lying Alternate Butterfly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Alternate between sides/arms/legs with each repetition. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'groin_stretch', 'Lying Butterfly - Alternating', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a686b684-efef-409d-ad81-00d9403fe952', 'Standing Single Leg Calf Raise (Barbell)', 'Legs', 'Barbell', '{"Calves"}'::text[], '{}'::text[], 'The Barbell Standing Single Leg Calf Raise isolates your calf muscles through a raising motion. The standing position engages your core for stability. Using a barbell provides stability for progressive overload. Lower body strength improves everything from walking to heavy compound lifts.', '107221201', '107221201-Barbell-Standing-Single-Leg-Calf-Raise-(female)_C.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Grip a barbell with hands at the appropriate width for Barbell Standing Single Leg Calf Raise. 2. Stand with feet about shoulder-width apart. 3. Lower your heels below the platform to get a full stretch. 4. Rise up onto your toes as high as possible, squeezing your calves. 5. Lower with control and repeat. 6. Complete all reps on one side, then switch to the other side. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 89, 5, 7, FALSE, TRUE, 'calf_raise', 'Standing Single Leg Calf Raise', 'calf_raise, seated_calf_raise', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('a6933431-b37e-4815-bf41-9aa2437ea697', 'Standing Face Pull To Y Raise (Band)', 'Shoulders', 'Resistance Band, Anchor Point', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'The Band Standing Face Pull To Y Raise is a pulling exercise that targets your delts for shoulder development. The upper back, rotator cuff assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. Resistance bands provide accommodating resistance that increases through the range of motion. Shoulder development enhances both performance and upper body aesthetics.', '107261201', '107261201-Band-Standing-Face-Pull-to-Y-Raise_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Secure the resistance band appropriately for Band Standing Face Pull To Y Raise. 2. Stand with feet about shoulder-width apart. 3. Raise the weight in the prescribed direction for Band Standing Face Pull To Y Raise. 4. Lower with control, maintaining tension throughout. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 87, 5, 7, FALSE, TRUE, 'face_pull', 'Standing Face Pull To Y Raise', 'rear_delt_fly, bent_over_row, lateral_raise', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('a6b1fa43-452c-40d7-98d5-52df70da18bb', 'Lying Heel Touchers - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. You''ll also feel your abs working to support the movement. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '38011201', '38011201-Alternate-Heel-Touchers-(female)_waist.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Alternate between sides/arms/legs with each repetition. 2. Set up in the starting position for Alternate Heel Touchers. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, 'Static', 'Isolation', 'Bilateral (Alternating)', NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Heel Touchers - Alternating', 'crunch, bicycle_crunch, russian_twist', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a6b4bfd5-9b95-40ea-a264-b597f84e6cbe', 'Landmine Romanian Deadlift (Landmine)', 'Legs', 'Landmine Attachment, Barbell', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. You''ll also feel your glutes, lower back working to support the movement. Strong legs are the foundation for athletic performance and functional fitness. Excellent for pre-exhausting the target muscle before compound lifts.', '57571201', '57571201-Landmine-Romanian-Deadlift-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Push your hips back, lowering the weight along your legs with a flat back. 2. Lower until you feel a stretch in your hamstrings. 3. Drive hips forward to stand, squeezing glutes at the top. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Landmine Romanian Deadlift', 'deadlift, leg_curl, hip_thrust', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('a6b57da5-62d3-4c7c-8615-e370156565fa', 'Standing Behind Back 180 Stretch - Alternating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your back, the Standing Alternating Behind Back 180 Stretch helps improve mobility and prevent stiffness. The shoulders assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '94681201', '94681201-Standing-Alternating-Behind-Back-180-Stretch-(fema.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Stand tall with your feet firmly planted. 2. Move into the stretch position for Standing Alternating Behind Back 180 Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Alternate between sides/arms/legs with each repetition.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Standing Behind Back 180 Stretch - Alternating', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a6c64ac9-a7e2-4208-adc7-b8102ce8d2e6', 'Criss Cross Jump', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Build power and athleticism with this high-intensity jumping exercise that challenges your entire body. You''ll also feel your quads, calves working to support the movement. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '71651201', '71651201-Criss-Cross-Jump-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Set up in the starting position for Criss Cross Jump. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'boxing', 'Criss Cross Jump', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('a6d0904b-2397-4c7a-9f12-5bb25e26e89c', 'Seated Straight Back Row (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Resistance bands provide accommodating resistance that increases through the range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '31211201', '31211201-Band-Seated-Straight-Back-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Seated Straight Back Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'back_exercise', 'Seated Straight Back Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('a6d5add7-37be-401f-9806-597696d2eae4', 'Prayer Squat Yoga Pose', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Designed to lengthen your quads, the Prayer Squat Yoga Pose helps improve mobility and prevent stiffness. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '43871201', '43871201-Prayer-Squat-Yoga-Pose_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. Maintain consistent tempo throughout the set.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'squat', 'Prayer Squat Yoga Pose', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a6da0b60-cf57-49d1-84b2-7c3ded170d6d', 'Chair Pose II Utkatasana II (Chair)', 'Full Body', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Chair Pose II Utkatasana II is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Flexibility work like this enhances performance and prevents stiffness.', '9431201', '09431201-Chair-Pose-II-Utkatasana-II-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Move into the stretch position for Chair Pose II Utkatasana II. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Chair Pose II Utkatasana II', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a6dc7dea-d007-4dcc-a60d-19fe45eefcc4', 'Decline Skull Press - Close Grip (Barbell)', 'Arms', 'Barbell, Decline Bench', '{"Triceps","Lower Chest"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Barbell Decline Close Grip To Skull Press targets your triceps through a pressing motion. The decline position targets the lower portion of the muscles more intensely. The barbell allows you to handle heavier loads for maximum strength gains. Arm strength supports grip, pulling, and pushing in compound movements.', '351201', '00351201-Barbell-Decline-Close-Grip-To-Skull-Press_Upper-Ar.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Grip a barbell with hands at the appropriate width for Barbell Decline Close Grip To Skull Press. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Execute the pressing motion for Barbell Decline Close Grip To Skull Press, extending through the target muscles. 4. Repeat for the prescribed number of repetitions.', 'Decline Press', 'Push', NULL, 'Bilateral', NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'general_exercise', 'Decline To Skull Press - Close Grip', 'Decline To Skull Press - Close Grip', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('a6decae0-bdc9-4df9-a527-a07322977ce2', 'Incline Bench Row - Reverse Grip (Barbell)', 'Back', 'Barbell, Incline Bench', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Your biceps, rear delts work as secondary movers, adding to the training stimulus. Using an incline changes the angle of resistance for varied muscle recruitment. The barbell allows you to handle heavier loads for maximum strength gains. Back development is crucial for pulling strength and overall upper body function.', '13171201', '13171201-Barbell-Reverse-Grip-Incline-Bench-Row_Back.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'incline_press', 'Incline Bench Row - Reverse Grip', 'Incline Bench Row - Reverse Grip', FALSE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('a6e34470-4148-4027-b168-9d3710bf330a', 'Air Punches March', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Hip Flexors"}'::text[], 'A challenging plyometric exercise, the Air Punches March builds reactive power and improves conditioning. Secondary activation of your hip flexors provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '98531201', '98531201-Air-Punches-March-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Set up in the starting position for Air Punches March. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, 'Push', 'Compound', 'Bilateral (Alternating)', NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'marching', 'Air Punches March', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a6e79ce5-b780-4a49-b92b-2fc4e1e03349', 'Bench Press (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Cable Bench Press, an effective pressing movement for upper body strength. Secondary activation of your triceps, front delts provides additional muscle engagement. Cables provide constant tension throughout the full range of motion. A well-developed chest contributes to upper body strength and aesthetics.', '1511201', '01511201-Cable-Bench-Press_Chest-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Adjust the cable machine to the correct height and attachment for Cable Bench Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 95, 7, 8, TRUE, TRUE, 'bench_press', 'Bench Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('a6f112ba-09ad-4a35-bb0a-9c106b7be54e', 'Standing Side Leg Lift Twist', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Abs"}'::text[], 'This dynamic twisting movement gets your heart rate up while developing explosive strength. You''ll also feel your abs working to support the movement. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '89141201', '89141201-Standing-Side-Leg-Lift-Twist-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:30.292204+00', '1. Stand tall with your feet firmly planted. 2. Rotate your torso through the movement pattern for Standing Side Leg Lift Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'russian_twist', 'Standing Side Leg Lift Twist', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a7061b6c-9db3-4807-9e0b-6ab95acbcbc3', 'High Knee Turn Sky Reach - Alternating', 'Legs', 'Bodyweight', '{"Hip Flexors"}'::text[], '{"Quads","Calves"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. You''ll also feel your hip flexors working to support the movement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '81731201', '81731201-Alternate-High-Knee-Turn-Sky-Reach-(female)_Plyome.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Alternate between sides/arms/legs with each repetition. 2. Set up in the starting position for Alternate High Knee Turn Sky Reach. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'high_knees', 'High Knee Turn Sky Reach - Alternating', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('a70e6679-9a54-40af-9a69-6daf21f87af2', 'Jump Split', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'A challenging plyometric exercise, the Jump Split builds reactive power and improves conditioning. The quads, calves assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '5121201', '05121201-Jump-Split-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Set up in the starting position for Jump Split. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'squat_jump', 'Jump Split', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('a71cde1c-dab4-47ac-952e-1ae0535110bd', 'Kneeling Elbow Mobilisation', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Kneeling Elbow Mobilisation is a movement exercise that develops back strength and muscle. Kneeling helps eliminate lower body momentum from the movement. A versatile bodyweight movement perfect for home or gym training. Back development is crucial for pulling strength and overall upper body function.', '90751201', '90751201-Kneeling-Elbow-Mobilisation-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Set up in the starting position for Kneeling Elbow Mobilisation. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Kneeling Elbow Mobilisation', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a7226191-c944-4b40-baf4-816ca099e5ae', 'Pike Push Up (On Bench)', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pushing movement that develops pressing power. Your triceps, front delts work as secondary movers, adding to the training stimulus. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '74261201', '74261201-Pike-Push-up-(on-Bench)-(VERSION-2)-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Pike Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a75bc19d-4bb2-4ae5-943c-d7080249c69f', 'Curl (Barbell)', 'Arms', 'Barbell', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Secondary activation of your forearms provides additional muscle engagement. Barbells enable bilateral loading for building raw strength. Dedicated arm training builds both strength and muscular definition.', '311201', '00311201-Barbell-Curl_Upper-Arms-FIX2_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Grip a barbell with hands at the appropriate width for Barbell Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', 'Isolation', 'Compound', NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, 'Underhand (Supinated)', 'Standard', 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'bicep_curl', 'Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('a76a4689-2577-46a1-a2ad-3ff89827ae49', 'Roll Quadriceps (vastus Lateralis) Lying On Floor', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Roll Quadriceps (vastus Lateralis) Lying On Floor is a core movement exercise that primarily targets your core. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '54321201', '54321201-Roll-Quadriceps-(Vastus-Lateralis)-Lying-on-Floor-.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Position yourself on the floor for Roll QuadricepsLying On Floor. 2. Lie down in the appropriate position for Roll QuadricepsLying On Floor. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'back_exercise', 'Roll Quadriceps Lying On Floor', 'Roll Quadriceps Lying On Floor', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a779f821-8ba6-4e07-9846-59a634d71ee5', 'Incline Plank (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'This stabilization exercise engages your abs for improved core stability and strength. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. Using an incline changes the angle of resistance for varied muscle recruitment. Suspension training adds instability, increasing core activation throughout. Core strength is foundational for athletic performance and injury prevention.', '94971201', '94971201-Suspender-Incline-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Incline Plank. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 63, 7, 8, TRUE, TRUE, 'plank', 'Suspender Incline Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'trx', TRUE, 3, 90, 4, 68, 85, 85, 70),
('a793b6a4-8c41-4cac-9cbf-9c04207e695b', 'Lying Supine Curl (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. The forearms assist throughout the movement, making this a well-rounded exercise. The lying position provides back support and helps isolate the target muscles. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements.', '3501201', '03501201-Dumbbell-Lying-Supine-Curl_Forearms.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Supine Curl. 2. Lie on your back with your body relaxed but ready. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'bicep_curl', 'Lying Supine Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('a79625e9-7a08-4f46-85eb-9c7ff3b9f084', 'Lying Straight Leg Circle - Alternating', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build leg strength with this movement movement focusing on your delts. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '60201201', '60201201-Lying-Alternate-Straight-Leg-Circle-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Alternate Straight Leg Circle. 2. Alternate between sides/arms/legs with each repetition. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'romanian_deadlift', 'Lying Straight Leg Circle - Alternating', 'deadlift, leg_curl, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a79c8b69-d996-447a-844b-b2e1d91fb2dc', 'Headstand (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Suspender Headstand is a core movement exercise that primarily targets your abs. Suspension training adds instability, increasing core activation throughout. Building core stability helps with everything from heavy deadlifts to daily activities.', '97041201', '97041201-Suspender-Headstand-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Headstand. 2. Set up in the starting position for Suspender Headstand. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'yoga', 'Suspender Headstand', 'squat, bench_press, deadlift', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('a79d3b34-544b-4dd4-8a4f-59d0c9fe84c4', 'Standing Back Wrist Curl', 'Arms', 'Bodyweight', '{"Forearms"}'::text[], '{}'::text[], 'The Barbell Standing Back Wrist Curl strengthens your forearms and grip through a curling motion. The forearms assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. Barbells enable bilateral loading for building raw strength. Dedicated arm training builds both strength and muscular definition.', '24811201', '24811201-Barbell-Standing-Back-Wrist-Curl-(female)_Forearms.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Grip a barbell with hands at the appropriate width for Barbell Standing Back Wrist Curl. 2. Stand tall with your feet firmly planted. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', 'Isolation', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, 'Overhand', 'Narrow', 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'wrist_curl', 'Standing Back Wrist Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a79d9bf3-adb3-4bba-b7f3-15de0077bb4a', 'Static Lunge Kick', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness. Maintain proper breathing - exhale during the effort phase.', '39661201', '39661201-Static-Lunge-Kick_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Static Lunge Kick', 'split_squat, step_up, squat', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('a7a26103-2554-4438-a929-794838c31487', 'Quadriceps Lying Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target your quads with this stretching stretch that helps restore range of motion. The lying position provides back support and helps isolate the target muscles. Flexibility work like this enhances performance and prevents stiffness. Progress gradually by increasing resistance over time.', '42991201', '42991201-Quadriceps-lying-stretch-(male)_Thighs.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Lie down in the appropriate position for Quadriceps Lying Stretch. 2. Move into the stretch position for Quadriceps Lying Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Quadriceps Lying Stretch', 'stretch_hip, stretch_hamstring', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a7b425cd-b32c-41b2-96df-1c726ba60021', 'Brachialis Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Brachialis Pull Up is an arm pulling exercise targeting your lats. Your biceps, upper back work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Dedicated arm training builds both strength and muscular definition.', '106931201', '106931201-Brachialis-Pull-up-(female)_Forearms_.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Complete all reps with control before resting. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Brachialis Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a7c1b084-40d2-4b30-a45b-8d5c63ccd43b', 'Rear Delt Raise (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'This raising exercise works your rear delts for improved shoulder strength and aesthetics. You''ll also feel your upper back working to support the movement. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '34291201', '34291201-Dumbbell-Rear-Delt-Raise-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Rear Delt Raise. 2. Raise your arms out to the sides and back, focusing on rear delts. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'rear_delt', 'Rear Delt Raise', 'shoulder_press, lateral_raise, face_pull, bent_over_row', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('a7caed7b-67ca-4ed9-ab1b-05186705b511', 'Lying On Floor Chest Press (Dumbbell)', 'Chest', 'Dumbbells', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. You''ll also feel your triceps, front delts working to support the movement. Performing this lying down removes momentum for stricter form. Dumbbells allow each arm to work independently, helping correct imbalances. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '74281201', '74281201-Dumbbell-Lying-on-Floor-Chest-Press-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying On Floor Chest Press. 2. Position yourself on the floor for Dumbbell Lying On Floor Chest Press. 3. Lie down in the appropriate position for Dumbbell Lying On Floor Chest Press. 4. Lower the weight toward your chest with control. 5. Press the weight up until your arms are extended (don''t lock elbows). 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'bench_press', 'Lying On Floor Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('a7cbb12a-8185-4473-a176-3d9cafc75f2e', 'Over Bench Reverse Wrist Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Forearms"}'::text[], '{}'::text[], 'Build grip strength and forearm size with this curling exercise. Secondary activation of your forearms provides additional muscle engagement. Dumbbells allow each arm to work independently, helping correct imbalances. Dedicated arm training builds both strength and muscular definition.', '26301201', '26301201-Dumbbell-Over-Bench-Reverse-Wrist-Curl-(female)_Fo.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Over Bench Reverse Wrist Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'wrist_curl', 'Over Bench Reverse Wrist Curl', 'hammer_curl, wrist_curl, bicep_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('a7cf27d3-97d3-473e-93f6-4acc35d9662c', 'Child Pose Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This stretch specifically works on your chest, promoting flexibility and reducing muscle tightness. Your hips work as secondary movers, adding to the training stimulus. Include this in your routine for better mobility and reduced muscle tension.', '48231201', '48231201-Child-Pose-Push-up_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'back_stretch', 'Child Pose Push Up', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a7d6b3d6-a56b-4b85-ab33-4da8ffaf1aab', 'Half Wipers (Bent Leg)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention. Perfect for including in both strength and hypertrophy programs.', '12481201', '12481201-Half-Wipers-(bent-leg)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Set up in the starting position for Half Wipers. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Half Wipers', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a7e83fc1-8d35-4be2-873c-22f8fcb20b63', 'Decline Chest Press (Cable)', 'Chest', 'Cables', '{"Chest","Lower Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. Your triceps work as secondary movers, adding to the training stimulus. Declining shifts the emphasis to hit the muscles from a different angle. The cable setup allows you to adjust the angle of resistance. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '12611201', '12611201-Cable-Decline-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Adjust the cable machine to the correct height and attachment for Cable Decline Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Continue for your target rep count, maintaining good form throughout.', 'Decline Press', 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 83, 7, 8, TRUE, TRUE, 'decline_press', 'Decline Press', 'bench_press, incline_bench_press, chest_fly, dip', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('a7f5ea20-95e4-44a3-824f-aa07c0bfcd1e', 'Goblet Split Squat Front Foot Elevated (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The dumbbell variation provides freedom of movement and greater range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '29551201', '29551201-Dumbbell-Goblet-Split-Squat-Front-Foot-Elevanted-(female)_Thighs-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Goblet Split Squat Front Foot Elevanted. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'split_squat', 'Goblet Split Squat Front Foot Elevanted', 'squat, front_squat, lunge', TRUE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('a7fc2e99-8656-4cda-9952-80120c29342d', 'Single Arm Snatch (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Target your delts with the Kettlebell One Arm Snatch, an effective shoulder movement exercise. Your quads, shoulders work as secondary movers, adding to the training stimulus. The kettlebell''s offset center of mass increases the stability challenge. Strong shoulders improve overhead strength and support nearly all upper body movements.', '5421201', '05421201-Kettlebell-One-Arm-Snatch_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Select an appropriately weighted kettlebell for Kettlebell One Arm Snatch. 2. Explosively pull the weight from the floor/hang position. 3. As it rises, pull yourself under and catch it overhead with locked arms. 4. Stand to complete the lift. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 53, 7, 8, TRUE, TRUE, 'snatch', 'Single Arm Snatch', 'power_snatch, clean, overhead_press', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('a7ff7788-c4fb-4750-9350-fbf0cc19b53d', 'Front Leg Lift Under Knee Tap', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning. Aim for full range of motion on every rep.', '56021201', '56021201-Front-Leg-Lift-Under-Knee-Tap-(female)_Plyometrics.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Set up in the starting position for Front Leg Lift Under Knee Tap. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Front Leg Lift Under Knee Tap', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a800960c-a573-401a-be60-9ac90c7d04cf', 'Fly (TRX)', 'Chest', 'TRX', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This flying exercise focuses on your pectorals for improved chest strength and development. Secondary activation of your front delts provides additional muscle engagement. Suspension training adds instability, increasing core activation throughout. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '10741201', '10741201-Suspender-Fly_Chest-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'chest_fly', 'Suspender Fly', 'bench_press, incline_press, push_up', FALSE, 'trx', FALSE, 3, 60, 2, 68, 85, 85, 70),
('a800fcf0-3640-49e7-8d85-a5978f78ec75', 'Wide Prone Hip Stretch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Target your hips with this stretching stretch that helps restore range of motion. Performing this lying down removes momentum for stricter form. Flexibility work like this enhances performance and prevents stiffness.', '84411201', '84411201-Wide-Prone-Hip-Stretch-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Lie face down (prone position) for Wide Prone Hip Stretch. 2. Move into the stretch position for Wide Prone Hip Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_stretch', 'Wide Prone Hip Stretch', 'stretch_hamstring, stretch_glute, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a808e816-0edd-49af-9724-c40f5053073d', 'Standing Back Clap And Elbow Touch And Prayer Push', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This pushing exercise engages your abs for improved core stability and strength. You''ll also feel your obliques working to support the movement. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '94731201', '94731201-Standing-Back-Clap-And-Elbow-Touch-And-Prayer-Push.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Back Clap And Elbow Touch And Prayer Push. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'boxing', 'Standing Back Clap And Elbow Touch And Prayer Push', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a80ccda9-cb30-493c-b397-7110d768e375', 'Lying Row On Rack - Neutral Grip (Dumbbell)', 'Back', 'Dumbbells, Flat Bench', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Secondary activation of your biceps, rear delts provides additional muscle engagement. The lying position provides back support and helps isolate the target muscles. The dumbbell variation provides freedom of movement and greater range of motion. Back development is crucial for pulling strength and overall upper body function.', '87231201', '87231201-Dumbbell-Lying-Neutral-Grip-Row-on-Rack_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Neutral Grip Row On Rack. 2. Lie down in the appropriate position for Dumbbell Lying Neutral Grip Row On Rack. 3. Use a neutral grip with palms facing each other. 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, 'Lying', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'general_exercise', 'Lying Row On Rack - Neutral Grip', 'Lying Row On Rack - Neutral Grip', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('a812436b-e060-4ec1-8093-7bb594a10c38', 'Hammer Preacher Curl (Dumbbell)', 'Arms', 'Dumbbells, Preacher Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Dumbbell Hammer Preacher Curl is a curling exercise that isolates your biceps. Secondary activation of your forearms provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements.', '59211201', '59211201-Dumbbell-Hammer-Preacher-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Hammer Preacher Curl. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'preacher_curl', 'Hammer Preacher Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('a8125a39-3dff-4614-8f9d-15e9a0395dd3', 'Plyo Push Up (Medicine Ball)', 'Chest', 'Medicine Ball', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Medicine Ball Plyo Push Up, an effective pushing movement for upper body strength. Secondary activation of your triceps, front delts provides additional muscle engagement. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '76151201', '76151201-Medicine-Ball-Plyo-Push-Up-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:30.292204+00', '1. Hold a medicine ball at the appropriate position for Medicine Ball Plyo Push Up. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'push_up', 'Medicine Ball Plyo Push Up', 'bench_press, chest_fly, dip', TRUE, 'medicine_ball', FALSE, 3, 60, 4, 70, 88, 95, 65),
('a81715a2-7e64-48ab-a348-58e98a168dfe', 'Incline Triceps Extension (EZ Bar)', 'Arms', 'EZ Bar, Incline Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this extension exercise for bigger arms. Using an incline changes the angle of resistance for varied muscle recruitment. The barbell allows you to handle heavier loads for maximum strength gains. Dedicated arm training builds both strength and muscular definition.', '97401201', '97401201-EZ-Barbell-Incline-Triceps-Extension-(female)_Uppe.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Grip a barbell with hands at the appropriate width for EZ Barbell Incline Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 95, 5, 7, FALSE, TRUE, 'tricep_extension', 'EZ Incline Triceps Extension', 'EZ Incline Triceps Extension', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('a821e928-6571-484d-a172-989d104f9b86', 'Backhand Raise', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Backhand Raise targets your rear deltoids with a raising motion. No equipment needed—your body provides all the resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '46631201', '46631201-Backhand-Raise-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Raise the weight in the prescribed direction for Backhand Raise. 2. Lower with control, maintaining tension throughout. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'back_exercise', 'Backhand Raise', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a84af3a4-85a8-4a19-92d1-47c2a556e0bc', 'Standing Front Leg Lift Cross Toe Touches (Version 2)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Standing Front Leg Lift Cross Toe Touches (version, focusing on your abs. Secondary activation of your hip flexors provides additional muscle engagement. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '78931201', '78931201-Standing-Front-Leg-Lift-Cross-Toe-Touches-(VERSION.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Front Leg Lift Cross Toe Touches (version. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'toe_touch', 'Standing Front Leg Lift Cross Toe Touches (version', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a85addbd-d8d3-443f-b272-e12181371557', 'Stepback With Prayer Push', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Stepback With Prayer Push is an explosive exercise that combines cardiovascular training with dynamic pushing movements. You''ll also feel your quads working to support the movement. Plyometric training builds explosive power that transfers to sports and daily activities.', '77381201', '77381201-Stepback-with-Prayer-Push-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Stepback With Prayer Push. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'boxing', 'Stepback With Prayer Push', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a85b6742-f1e7-4e1b-99e0-5bd7cbce6b03', 'Bridge Leg Lift - Alternating', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'This bridging exercise isolates your glutes for improved hip strength and power. Your hamstrings work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '84851201', '84851201-Bridge-Alternate-Leg-Lift-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Alternate between sides/arms/legs with each repetition. 5. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Bridge Leg Lift - Alternating', 'hip_thrust, romanian_deadlift, leg_curl', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a8612d3e-2ea3-401d-b2a4-e6f09174abd9', 'Lying Reverse Twist', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Abs"}'::text[], 'The Lying Reverse Twist provides a deep stretch for your full body, ideal for recovery and mobility work. The abs assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. Flexibility work like this enhances performance and prevents stiffness.', '85931201', '85931201-Lying-Reverse-Twist-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Lie down in the appropriate position for Lying Reverse Twist. 2. Rotate your torso through the movement pattern for Lying Reverse Twist. 3. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Lying Reverse Twist', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a864cf67-1068-44e5-86cc-e58aeb454af1', 'Seated Shoulder Stretch Behind The (Resistance Band)', 'Shoulders', 'Resistance Band', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Use this stretch to open up your shoulders area and enhance overall flexibility. Secondary activation of your upper back provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Bands are joint-friendly and portable, perfect for any training environment. Flexibility work like this enhances performance and prevents stiffness.', '87351201', '87351201-Resistance-Band-Seated-Shoulder-Stretch-Behind-the.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Seated Shoulder Stretch Behind The. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Resistance Band Seated Shoulder Stretch Behind The. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Maintain a neutral spine throughout. Beneficial for overall stretching development.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 37, 2, 6, FALSE, TRUE, 'shoulder_stretch', 'Seated Shoulder Stretch Behind The', 'stretch_chest, stretch_tricep, stretch_lat', FALSE, 'band', TRUE, 1, 30, 2, 60, 85, 90, 50),
('a87744c2-facf-40d1-bcd1-f1866278dc0e', 'Side Lunge Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'Designed to lengthen your quads, the Side Lunge Stretch helps improve mobility and prevent stiffness. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '89711201', '89711201-Side-Lunge-Stretch-(VERSION-2)-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Step to the side, bending that knee while keeping the other leg straight. 2. Push through your front/working leg to return to the starting position. 3. Move into the stretch position for Side Lunge Stretch. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 6. Switch sides and repeat for equal time. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 60, 2, 6, FALSE, TRUE, 'hip_stretch', 'Side Lunge Stretch', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a8802ad8-1b8d-46e3-9deb-1a376d1a020c', 'Hands Up Knee Drive', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Hands Up Knee Drive builds reactive power and improves conditioning. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '89841201', '89841201-Hands-Up-Knee-Drive-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Set up in the starting position for Hands Up Knee Drive. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'knee_drive', 'Hands Up Knee Drive', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a884e129-2fc7-4d25-8017-449da72220af', 'Split Squat Front Foot Elevated', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Bodyweight Split Squat Front Foot Elevanted is a squatting exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '77831201', '77831201-Bodyweight-Split-Squat-Front-Foot-Elevanted_Thighs.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement. A solid choice for legs day.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'split_squat', 'Split Squat Front Foot Elevanted', 'lunge, bulgarian_split_squat, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a8870124-b6d2-4bdf-8d42-97851e7304ea', 'Standing Torso Twist Arms Swing', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This twisting movement focuses on your obliques for a complete core workout. The abs assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '95231201', '95231201-Standing-Torso-Twist-Arms-Swing-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Begin in a standing position with good posture. 2. Rotate your torso through the movement pattern for Standing Torso Twist Arms Swing. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'russian_twist', 'Standing Torso Twist Arms Swing', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a88e3712-22c1-4433-8423-5027ef86c1aa', 'Seated Bicep Curl (Cable)', 'Arms', 'Cables, Flat Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Cable Seated Unilateral Biceps Curl is a curling exercise that isolates your biceps. You''ll also feel your forearms working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Cable resistance creates smooth, continuous muscle engagement. Arm strength supports grip, pulling, and pushing in compound movements.', '79211201', '79211201-Cable-Seated-Unilateral-Bicep-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Unilateral Biceps Curl. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'bicep_curl', 'Seated Unilateral Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('a89010d3-7e78-48a9-be64-6a206a2f9e5a', 'Arm Raise Step In Place', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'A challenging plyometric exercise, the Arm Raise Step In Place builds reactive power and improves conditioning. The quads assist throughout the movement, making this a well-rounded exercise. Plyometric training builds explosive power that transfers to sports and daily activities.', '60151201', '60151201-Arm-Raise-Step-in-Place-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Set up a box or step platform at the appropriate height. 2. Raise the weight in the prescribed direction for Arm Raise Step In Place. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'arm_exercise', 'Arm Raise Step In Place', 'shoulder_press, lateral_raise, front_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a89029f0-f911-4979-b3d2-5f2671ee2d1d', 'Superman (TRX) - Alternating', 'Back', 'TRX', '{"Lower Back"}'::text[], '{"Glutes","Upper Back"}'::text[], 'The Suspender Alternate Superman is a core movement exercise that primarily targets your abs. You''ll also feel your glutes working to support the movement. The TRX allows you to adjust difficulty by changing your body angle. Core strength is foundational for athletic performance and injury prevention.', '47981201', '47981201-Suspender-Alternate-Superman_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Alternate Superman. 2. Alternate between sides/arms/legs with each repetition. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'back_extension', 'Suspender Superman - Alternating', 'squat, bench_press, deadlift', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('a894063f-d8d6-41a0-830c-d362c622ddae', 'Russian Twist To Single Arm Press (Dumbbell)', 'Core', 'Dumbbells', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this pressing exercise that strengthens your obliques. You''ll also feel your abs working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. A strong core improves posture, protects your spine, and enhances all other lifts.', '93401201', '93401201-Dumbbell-Russian-Twist-to-Single-Arm-Press_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Execute the pressing motion for Dumbbell Russian Twist To Single Arm Press, extending through the target muscles. 3. Complete all reps on one side, then switch to the other side. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'russian_twist', 'Russian Twist To Single Arm Press', 'crunch, plank, leg_raise, wood_chop', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('a8b0190b-8ffe-4a70-8a17-2cbd0a5c21b3', 'Seated Chest Clam', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Shoulders"}'::text[], 'Target your chest with this movement stretch that helps restore range of motion. Secondary activation of your shoulders provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. Flexibility work like this enhances performance and prevents stiffness.', '49461201', '49461201-Seated-Chest-Clam_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Chest Clam. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'hip_abduction', 'Seated Chest Clam', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a8ba8a5b-9987-4ae8-82f9-0cefcb9afcfb', 'Single Arm Side Press (Kettlebell)', 'Core', 'Kettlebell', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Kettlebell Single Arm Side Press, focusing on your abs. Kettlebells are excellent for building functional, real-world strength. A strong core improves posture, protects your spine, and enhances all other lifts.', '98471201', '98471201-Kettlebell-Single-Arm-Side-Press-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Select an appropriately weighted kettlebell for Kettlebell Single Arm Side Press. 2. Execute the pressing motion for Kettlebell Single Arm Side Press, extending through the target muscles. 3. Complete all reps on one side, then switch to the other side. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 73, 7, 8, TRUE, TRUE, 'arm_exercise', 'Single Arm Side Press', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('a8c0e63f-b364-47f0-b55c-23b81dd8b6c6', 'Walk Elliptical Machine (Elliptical)', 'Legs', 'Elliptical', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build your aerobic capacity with this steady-state cardio movement. The machine guides your movement path for safer, more controlled repetitions. Cardiovascular exercise improves heart health, endurance, and helps manage weight.', '22631201', '22631201-Elliptical-Machine-Walk-(female)_Cardio.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Elliptical Machine Walk. 2. Set up in the starting position for Elliptical Machine Walk. 3. Execute the movement with proper form, focusing on your cardio. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, FALSE, NULL, 'Cardio', 58, 9, 8, FALSE, TRUE, 'elliptical', 'Elliptical  Walk', 'Elliptical Walk', FALSE, 'machine', TRUE, 1, 60, 4, 80, 75, 20, 88),
('a8c245e9-9fe7-439e-8e9f-55cea863128d', 'Incline Mountain Climber On Stepbox (Step Platform)', 'Core', 'Step Platform', '{"Abs"}'::text[], '{"Hip Flexors","Shoulders"}'::text[], 'This climbing exercise engages your abs for improved core stability and strength. The hip flexors, shoulders assist throughout the movement, making this a well-rounded exercise. The incline angle shifts emphasis toward the upper portion of the target muscles. Core strength is foundational for athletic performance and injury prevention.', '87081201', '87081201-Incline-Mountain-Climber-on-Stepbox-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Set up a box or step platform at the appropriate height. 2. From plank position, drive one knee toward your chest. 3. Quickly switch legs, bringing the other knee forward. 4. Continue alternating at a quick pace while maintaining plank form. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 53, 9, 8, TRUE, TRUE, 'mountain_climber', 'Incline Mountain Climber On Stepbox', 'burpee, plank, high_knees', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('a8c5a951-c24d-4237-9dac-660a9d6f64cd', 'Self Assisted Chin Up - Neutral Grip (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this movement movement. Your biceps work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '80091201', '80091201-Self-Assisted-Neutral-Grip-Chin-Up-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Use a neutral grip with palms facing each other. 2. Pull yourself up, focusing on bicep and lat engagement. 3. Raise until chin is over the bar, lower with full control. 4. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Self Assisted Chin Up - Neutral Grip', 'Self Assisted Chin Up - Neutral Grip', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a8cae647-8a0c-4db5-96b6-6b3ccfbdc197', 'Elevated Goblet Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength. This variation is excellent for building mind-muscle connection.', '93961201', '93961201-Elevanted-Goblet-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Keep your core engaged for stability. Ideal for quads strength and endurance.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'goblet_squat', 'Elevanted Goblet Squat', 'squat, front_squat, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a8cec47d-dc15-4b16-a7dd-2a2f5b0d12ba', 'Elevated Split Squat (Smith Machine)', 'Legs', 'Smith Machine, Step Platform', '{Quadriceps}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Machine exercises are great for isolating muscles and training to failure safely. Leg training boosts metabolism and builds functional, real-world strength.', '90421201', '90421201-Smith-Elevated-Split-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Elevated Split Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'split_squat', 'Smith Elevated Split Squat', 'Elevated Split Squat', FALSE, 'smith_machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('a8d76be2-a175-4c4c-b4a5-c5834a4df3c3', 'Decline Crunch (Decline Bench)', 'Core', 'Decline Bench', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Decline Crunch, focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. The decline position targets the lower portion of the muscles more intensely. Building core stability helps with everything from heavy deadlifts to daily activities.', '2771201', '02771201-Decline-Crunch_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', 'Press', NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 73, 5, 7, FALSE, TRUE, 'crunch', 'Decline Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a8ebda78-e747-429c-8aa2-9e6e86494d8c', 'Calf Raise And Front Squat (Kettlebell)', 'Legs', 'Kettlebell', '{"Quads"}'::text[], '{"Glutes","Core"}'::text[], 'Build stronger calves with this targeted squatting exercise. You''ll also feel your glutes, hamstrings working to support the movement. Kettlebells are excellent for building functional, real-world strength. Strong legs are the foundation for athletic performance and functional fitness.', '58801201', '58801201-Kettlebell-Calf-Raise-and-Front-Squat-(male)_Thigh.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Select an appropriately weighted kettlebell for Kettlebell Calf Raise And Front Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 100, 5, 7, FALSE, TRUE, 'front_squat', 'Calf Raise And Front Squat', 'squat, leg_press, leg_extension, goblet_squat', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('a8f45401-c59f-4562-8721-77d70b30d284', 'Oblique Crunch - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{}'::text[], 'Build a stronger core with the Alternate Oblique Crunch, focusing on your abs. Secondary activation of your abs provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '43541201', '43541201-Alternate-Oblique-Crunch_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Alternate between sides/arms/legs with each repetition. 5. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', NULL, 'Pull', 'Compound', 'Bilateral (Alternating)', NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Oblique Crunch - Alternating', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a8faca09-18e9-4597-bf60-e75ff8fb53f1', 'Plank 4 Point Hops', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'A challenging plyometric exercise, the Plank 4 Point Hops builds reactive power and improves conditioning. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '104131201', '104131201-Plank-4-Point-Hops-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'plank', 'Plank 4 Point Hops', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 60, 4, 70, 88, 95, 65),
('a8fc7a2a-b836-4d27-ba4b-84612470a058', 'Lying Woodchopper Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{}'::text[], 'Work your side abdominals with this crunching exercise that strengthens your obliques. The hip flexors assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '105201201', '105201201-Lying-Woodchopper-Crunch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Lie down in the appropriate position for Lying Woodchopper Crunch. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'woodchop', 'Lying Woodchopper Crunch', 'plank, leg_raise, russian_twist, sit_up', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('a91026e7-d257-46a9-ab31-85d9a5b728d6', 'World Greatest Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The World Greatest Stretch provides a deep stretch for your full body, ideal for recovery and mobility work. Your hips, hamstrings, thoracic spine work as secondary movers, adding to the training stimulus. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '82681201', '82681201-World-Greatest-Stretch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:40.146812+00', '1. Move into the stretch position for World Greatest Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'World Greatest Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a91105f3-4fba-4f9a-83e4-43f0f89dea15', 'Lying Single Leg Extension (Machine)', 'Legs', 'Leg Extension Machine', '{"Quads"}'::text[], '{}'::text[], 'Build stronger quads with this extension movement that develops leg drive and power. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '95251201', '95251201-Lying-Single-Leg-Extension-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Single Leg Extension. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Complete all reps on one side, then switch to the other side. 5. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'leg_extension', 'Lying Single Leg Extension', 'squat, leg_press, lunge', TRUE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('a9119fad-d87d-41c2-9773-6793025e43bb', 'Single Arm Front Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Strengthen your midsection with this stabilization movement that works your abs. Your shoulders, lower back work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '39831201', '39831201-One-Arm-Front-Plank_Waist-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps on one side, then switch to the other side. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'plank', 'Single Arm Front Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('a948820e-24b1-4b14-9217-743c22a0dbb1', 'Staggered Stance Deadlift (Barbell)', 'Back', 'Barbell', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'The Barbell Staggered Stance Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. Your glutes, lower back work as secondary movers, adding to the training stimulus. Barbells enable bilateral loading for building raw strength. Leg training boosts metabolism and builds functional, real-world strength.', '87001201', '87001201-Barbell-Staggered-Stance-Deadlift-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Grip a barbell with hands at the appropriate width for Barbell Staggered Stance Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'deadlift', 'Staggered Stance Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('a954365d-8912-4204-80f4-cb64c3b49d80', 'Side Lunge Overhead Reach', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'A challenging plyometric exercise, the Side Lunge Overhead Reach builds reactive power and improves conditioning. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '78441201', '78441201-Side-Lunge-Overhead-Reach-(female)_Plyometrics-col.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Step to the side, bending that knee while keeping the other leg straight. 2. Push through your front/working leg to return to the starting position. 3. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Side Lunge Overhead Reach', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a95928fa-4f82-4ecc-975f-1212002aff00', 'Hamstring Arm Lift (Gymnastic Rings) - Alternating', 'Full Body', 'Gymnastic Rings', '{"Full Body"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. Great for improving athletic performance, burning calories, and building conditioning. Progress gradually by increasing resistance over time.', '79471201', '79471201-Alternating-Hamstring-Arm-Lift-(female)_Plyometric.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Alternate between sides/arms/legs with each repetition. 2. Set up in the starting position for Alternating Hamstring Arm Lift. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 38, 7, 8, TRUE, TRUE, 'arm_exercise', 'Hamstring Arm Lift - Alternating', 'shoulder_press, lateral_raise, front_raise', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('a960db1a-03a9-404b-9063-a1195c2f095a', 'Pullover (Machine)', 'Chest', 'Lever Machine', '{"Chest"}'::text[], '{"Lats","Triceps"}'::text[], 'Build a stronger back with this pulling movement targeting your chest. The lats, triceps assist throughout the movement, making this a well-rounded exercise. The machine guides your movement path for safer, more controlled repetitions. Back development is crucial for pulling strength and overall upper body function.', '22851201', '22851201-Lever-Pullover-(plate-loaded)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Pullover. 2. With arms slightly bent, lower the weight behind your head in an arc. 3. Pull the weight back over your chest, squeezing your lats and chest. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'pullover', 'Lever Pullover', 'bicep_curl, face_pull, lat_pulldown', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('a9629d57-3e71-4b09-8f0d-18ea659f92dc', 'Standing Crunch (Band)', 'Core', 'Resistance Band', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This crunching exercise engages your abs for improved core stability and strength. Your hip flexors work as secondary movers, adding to the training stimulus. Performing this standing challenges your balance and core engagement. Bands are joint-friendly and portable, perfect for any training environment. A strong core improves posture, protects your spine, and enhances all other lifts.', '10051201', '10051201-Band-standing-crunch_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Secure the resistance band appropriately for Band Standing Crunch. 2. Begin in a standing position with good posture. 3. Curl your shoulders off the floor by contracting your abs. 4. Don''t pull on your neck—focus on the abdominal contraction. 5. Lower with control, maintaining some tension. 6. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'crunch', 'Standing Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('a96bfc49-c8f2-441c-a122-5939bbb44499', 'Warrior Pose II', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Hip Flexors","Core"}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. You''ll also feel your hips, shoulders, quads working to support the movement. Flexibility work like this enhances performance and prevents stiffness.', '62911201', '62911201-Warrior-Pose-II-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Move into the stretch position for Warrior Pose II. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Warrior Pose II', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a96e29ff-c780-4d58-8dbb-1052c0669e4e', 'Silent Burpee', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Chest","Quads","Core"}'::text[], 'The Silent Burpee is an explosive exercise that combines cardiovascular training with dynamic movement movements. Your chest, quads work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '47041201', '47041201-Silent-Burpee_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Squat down and place hands on the floor, jump feet back to plank. 2. Jump feet back toward hands, then explosively jump up with arms overhead. 3. Land softly and immediately begin the next rep. 4. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'burpee', 'Silent Burpee', 'mountain_climber, box_jump, jumping_jack', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('a96f3ce4-e66b-4717-9954-b42be5512490', 'Pullover Hip Extension (Stability Ball, Dumbbell)', 'Legs', 'Dumbbells, Stability Ball, Flat Bench', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'This pulling exercise focuses on your pectorals for improved chest strength and development. Secondary activation of your hamstrings provides additional muscle engagement. The dumbbell variation provides freedom of movement and greater range of motion. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '12941201', '12941201-Dumbbell-Pullover-Hip-Extension-on-Exercise-Ball_C.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Pullover Hip Extension On Exercise Ball. 2. Extend through the target joint(s) for Dumbbell Pullover Hip Extension On Exercise Ball. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 74, 5, 7, FALSE, TRUE, 'glute_kickback', 'Pullover Hip Extension On Exercise Ball', 'bicep_curl, face_pull, lat_pulldown', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('a9726d8f-5e2d-446e-84f3-b04bf08923a5', 'Weighted Table Top Bridge (Dumbbell)', 'Legs', 'Dumbbells', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this bridging movement focused on hip extension. The hamstrings assist throughout the movement, making this a well-rounded exercise. Dumbbells allow each arm to work independently, helping correct imbalances. Lower body strength improves everything from walking to heavy compound lifts.', '83501201', '83501201-Weighted-Dumbbell-Table-Top-Bridge-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Select a pair of dumbbells at an appropriate weight for Weighted Dumbbell Table Top Bridge. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'glute_bridge', 'Weighted Table Top Bridge', 'Weighted Table Top Bridge', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('a973354c-a7fb-4a04-b198-5bdf60b5f148', 'Wrist Ulnar Deviator And Flexor Stretch', 'Arms', 'Bodyweight', '{"Forearms"}'::text[], '{}'::text[], 'Target your wrists with this stretching stretch that helps restore range of motion. Flexibility work like this enhances performance and prevents stiffness.', '18251201', '18251201-Wrist-Ulnar-Deviator-And-Flexor-Stretch-(female)_F.mp4', 'female', FALSE, '2025-12-03 23:26:40.146812+00', '1. Move into the stretch position for Wrist Ulnar Deviator And Flexor Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Wrist Ulnar Deviator And Flexor Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a978e3f0-02c9-46b3-89f5-2da1dc3cacb8', 'Lateral Speed Step', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this stepping exercise that develops speed, power, and coordination. The quads assist throughout the movement, making this a well-rounded exercise. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '5651201', '05651201-Lateral-Speed-Step-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Lateral Speed Step. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Lateral Speed Step', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a9915706-790b-4155-ab3a-0d4c823db8e7', 'Seated Rotational Hip Stretch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Use this stretch to open up your hips area and enhance overall flexibility. Being seated provides stability, allowing you to focus on the working muscles. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '19481201', '19481201-Sitting-Rotational-Hip-Stretch-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:37.877283+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Rotational Hip Stretch. 3. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 32, 2, 6, FALSE, TRUE, 'hip_stretch', 'Seated Rotational Hip Stretch', 'stretch_hamstring, stretch_glute, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('a994a2ec-b0d5-43ec-978b-64d187a33290', 'Hyperextension (Barbell)', 'Back', 'Barbell, Hyperextension Bench', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Develop your posterior chain with this extension movement that emphasizes the glutes. The hamstrings, lower back assist throughout the movement, making this a well-rounded exercise. Barbells enable bilateral loading for building raw strength. Lower body strength improves everything from walking to heavy compound lifts.', '87971201', '87971201-Barbell-Hyperextension-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Grip a barbell with hands at the appropriate width for Barbell Hyperextension. 2. Raise your torso by extending at the lower back/hips. 3. Lower with control, maintaining tension. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'back_extension', 'Hyperextension', 'good_morning, bird_dog, superman', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('a999c539-15d6-4878-b829-88a28c10bc9f', 'Bench Press (Band)', 'Chest', 'Resistance Band, Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. Your triceps, front delts work as secondary movers, adding to the training stimulus. Bands are joint-friendly and portable, perfect for any training environment. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '12541201', '12541201-Band-Bench-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Secure the resistance band appropriately for Band Bench Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'bench_press', 'Bench Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('a9a3f02f-1063-43cc-8710-f320973986da', 'Sumo Squat And Side Knee Raise', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs","Hamstrings"}'::text[], 'This dynamic squatting movement gets your heart rate up while developing explosive strength. Secondary activation of your hip flexors provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '61741201', '61741201-Sumo-Squat-and-Side-Knee-Raise-(female)_Plyometric.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Raise your arms out to the sides until parallel to the floor. 2. Lower with control, maintaining tension throughout. 3. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'leg_raise', 'Sumo Squat And Side Knee Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a9b1f3a4-59b9-4dba-9293-b5a05767e69f', 'Lying Seal Row On Rack (Dumbbell)', 'Back', 'Dumbbells, Flat Bench', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Dumbbell Lying Seal Row On Rack is a rowing exercise that builds thickness in your upper back. Secondary activation of your biceps, rear delts provides additional muscle engagement. Performing this lying down removes momentum for stricter form. Dumbbells allow each arm to work independently, helping correct imbalances. Back development is crucial for pulling strength and overall upper body function.', '105721201', '105721201-Dumbbell-Lying-Seal-Row-on-Rack_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Seal Row On Rack. 2. Lie down in the appropriate position for Dumbbell Lying Seal Row On Rack. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, 'Lying', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'general_exercise', 'Lying Seal Row On Rack', 'lat_pulldown, bent_over_row, pull_up', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('a9d89666-dc17-428b-b8e7-f7b929b82760', 'Ring Russian Push Up (Gymnastic Rings)', 'Chest', 'Gymnastic Rings', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Ring Russian Push Up is a pushing exercise that targets your chest muscles. You''ll also feel your triceps, front delts working to support the movement. A well-developed chest contributes to upper body strength and aesthetics.', '75201201', '75201201-Ring-Russian-Push-Up-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep. Ideal for chest strength and endurance.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'push_up', 'Ring Russian Push Up', 'bench_press, chest_fly, dip', TRUE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('a9d97f10-b011-478e-a9b4-ece294d2153c', 'Cossack Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes, hamstrings provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '46321201', '46321201-Cossack-Squat_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum. An effective movement for your legs routine.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Cossack Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a9eb42c0-31c7-4e48-b1e1-13cdf62b9c55', 'Lying Arm Crossover', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Lying Arm Crossover is a movement exercise that targets your chest muscles. Secondary activation of your front delts provides additional muscle engagement. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics.', '90321201', '90321201-Lying-Arm-Crossover-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Arm Crossover. 2. Set up in the starting position for Lying Arm Crossover. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_fly', 'Lying Arm Crossover', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a9edef03-8888-4c6a-97f0-d114375d88c7', 'Lateral Lunge (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Using a barbell provides stability for progressive overload. Leg training boosts metabolism and builds functional, real-world strength.', '22281201', '22281201-Barbell-Lateral-Lunge-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Grip a barbell with hands at the appropriate width for Barbell Lateral Lunge. 2. Step to the side, bending that knee while keeping the other leg straight. 3. Push through your front/working leg to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'lunge', 'Lateral Lunge', 'split_squat, step_up, squat', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('a9ee6a9c-9570-49e7-aac4-e9dd9bd74543', 'Single Leg Extension (Stability Ball)', 'Legs', 'Stability Ball', '{"Quads"}'::text[], '{}'::text[], 'Target the front of your thighs with this extension exercise for quad development. Using a ball requires constant core engagement to maintain balance. Strong legs are the foundation for athletic performance and functional fitness.', '7281201', '07281201-Single-Leg-Extension-(on-stability-ball)-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Position the stability ball as needed for Single Leg Extension. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Complete all reps on one side, then switch to the other side. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 67, 5, 7, FALSE, TRUE, 'leg_extension', 'Single Leg Extension', 'squat, leg_press, lunge', FALSE, 'stability_ball', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a9f010a3-31a4-49f0-a0d3-f506d0e49008', 'Lying Frog Crunch Feet Together', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Lying Frog Crunch Feet Together, focusing on your abs. You''ll also feel your hip flexors working to support the movement. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '89761201', '89761201-Lying-Frog-Crunch-Feet-Together-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Lie down in the appropriate position for Lying Frog Crunch Feet Together. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Lying Frog Crunch Feet Together', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('a9f03ad9-84c2-4d46-81bb-0da755b613de', 'Lying Back Opener', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Shoulders"}'::text[], 'The Lying Back Opener is a flexibility exercise that targets your back, helping to release tension and improve range of motion. The shoulders assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '85911201', '85911201-Lying-Back-Opener-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Lie down in the appropriate position for Lying Back Opener. 2. Move into the stretch position for Lying Back Opener. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Lying Back Opener', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('a9f531b2-dcec-4717-8a6a-0e796157b64c', 'Seated Single Leg Knee Flexion', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This flexion movement works your hamstrings for balanced leg development. Being seated provides stability, allowing you to focus on the working muscles. Lower body strength improves everything from walking to heavy compound lifts.', '100001201', '100001201-Sitting-Single-Leg-Knee-Flexion-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:37.877283+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Complete all reps on one side, then switch to the other side. 3. Complete all reps with control before resting. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'leg_exercise', 'Seated Single Leg Knee Flexion', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('aa01ef9f-c07a-4376-b288-f7e0f083dc38', 'Standing Single Arm Triceps Pushdown Overhand Grip (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Cable Standing One Arm Triceps Pushdown (overhand G targets your triceps through a pushing motion. The standing position engages your core for stability. Cables provide constant tension throughout the full range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '12271201', '12271201-Cable-Standing-One-Arm-Tricep-Pushdown-(Overhand-G.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing One Arm Triceps Pushdown (overhand G. 2. Stand with feet about shoulder-width apart. 3. Use an overhand (pronated) grip with palms facing down/away. 4. Complete all reps on one side, then switch to the other side. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 39, 5, 7, FALSE, TRUE, 'tricep_pushdown', 'Standing Single Arm Triceps Pushdown', 'tricep_extension, close_grip_bench, dip', TRUE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('aa130d74-cc8d-4c39-a2c6-1fc2ae31021c', 'Wide Hand Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. Your triceps, front delts work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics.', '40371201', '40371201-Wide-Hand-Push-up-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement. This exercise is excellent for chest development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Wide Hand Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('aa22ff01-df7c-45e3-b170-5fa4b6695674', 'Side Up Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Side Up Squat is an explosive exercise that combines cardiovascular training with dynamic squatting movements. Secondary activation of your glutes, hamstrings provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '54671201', '54671201-Side-Up-Squat_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control. Great for building strength in your quads.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Side Up Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('aa35b6f6-84ea-4542-8acf-80a68e8498f2', 'Standing Twist Stretch (Stick)', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this stretching exercise that strengthens your obliques. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '54031201', '54031201-Stick-Standing-Twist-Stretch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Stand with feet about shoulder-width apart. 2. Rotate your torso through the movement pattern for Stick Standing Twist Stretch. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Stick Standing Twist Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('aa3ab8d1-9896-4cea-b868-c75eb455da69', 'Bench Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Bodyweight Bench Squat is a squatting exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '65411201', '65411201-Bodyweight-Bench-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement. A solid choice for legs day. Variation: Bodyweight Bench Squat.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Bench Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('aa3ecd5d-2efe-4461-a549-8aef85efce34', 'Back Squeeze', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This movement exercise works your delts for improved shoulder strength and aesthetics. No equipment needed—your body provides all the resistance. Strong shoulders improve overhead strength and support nearly all upper body movements. This is a great exercise for all fitness levels with proper scaling.', '54521201', '54521201-Back-Squeeze-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Set up in the starting position for Back Squeeze. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Back Squeeze', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('aa4c6e97-8725-4978-b076-6ffa9fce9879', 'Coner Wall Chest Stretch (Wall)', 'Chest', 'Wall, Cones', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Target your chest with the Coner Wall Chest Stretch, an effective stretching movement for upper body strength. A well-developed chest contributes to upper body strength and aesthetics.', '96001201', '96001201-Coner-Wall-Chest-Stretch-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Position yourself at the appropriate distance from a wall. 2. Set up in the starting position for Coner Wall Chest Stretch. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form. Ideal for chest strength and endurance.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 32, 2, 6, FALSE, TRUE, 'chest_stretch', 'Coner Wall Chest Stretch', 'stretch_shoulder, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('aa6ef55f-6a36-472e-8810-238b653d5beb', 'Single Leg Split Squat (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Dumbbells allow each arm to work independently, helping correct imbalances. Lower body strength improves everything from walking to heavy compound lifts.', '4101201', '04101201-Dumbbell-Single-Leg-Split-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 92, 7, 9, TRUE, FALSE, 'split_squat', 'Single Leg Split Squat', 'lunge, bulgarian_split_squat, squat', TRUE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('aa7ff0ae-f167-401b-8451-70bfe88d45ea', 'Stepback And Forward Kick', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this kicking exercise that develops speed, power, and coordination. You''ll also feel your quads working to support the movement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '71921201', '71921201-Stepback-and-Forward-Kick-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Stepback And Forward Kick. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Stepback And Forward Kick', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('aaa6c0bf-9e98-44ef-8daf-08436712f533', 'Pronated Grip Seated Row (Plate Loaded)', 'Back', 'Row Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Secondary activation of your biceps, lats provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. Machine exercises are great for isolating muscles and training to failure safely. Back development is crucial for pulling strength and overall upper body function.', '54471201', '54471201-Lever-Pronated-Grip-Seated-Row-(plate-loaded)_Back.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Pronated Grip Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use an overhand (pronated) grip with palms facing down/away. 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, 'Seated', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 90, 7, 9, TRUE, FALSE, 'cable_row', 'Lever Pronated Grip Seated Row', 'squat, bench_press, deadlift', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('aaaf4d94-8bef-4ddb-a7a6-42d8d67c3c34', 'Incline Triceps Extension Skull Crusher (Barbell)', 'Arms', 'Barbell, Incline Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. Using an incline changes the angle of resistance for varied muscle recruitment. The barbell allows you to handle heavier loads for maximum strength gains. Dedicated arm training builds both strength and muscular definition.', '43441201', '43441201-Barbell-Incline-Triceps-Extension-Skull-Crusher_Up.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Grip a barbell with hands at the appropriate width for Barbell Incline Triceps Extension Skull Crusher. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 95, 5, 7, FALSE, TRUE, 'tricep_extension', 'Incline Triceps Extension Skull Crusher', 'tricep_pushdown, close_grip_bench', TRUE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('aab40156-cde3-4fc7-b3be-eda646fa1844', 'Single Arm Triceps Extension On Bench (Dumbbell)', 'Arms', 'Dumbbells', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements.', '26011201', '26011201-Dumbbell-One-Arm-Triceps-Extension-(on-bench)-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Complete all reps on one side, then switch to the other side. 5. Complete all reps with control before resting. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 79, 5, 7, FALSE, TRUE, 'tricep_extension', 'Single Arm Triceps Extension', 'tricep_pushdown, close_grip_bench', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('aadadc2e-bc00-473c-93e6-3cf1ee18bec8', 'Prone Ts (TRX)', 'Shoulders', 'TRX', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Suspender Prone Ts targets your rear deltoids with a movement motion. You''ll also feel your upper back working to support the movement. The lying position provides back support and helps isolate the target muscles. Suspension training adds instability, increasing core activation throughout. A strong back improves posture, prevents injury, and balances pressing movements.', '75091201', '75091201-Suspender-Prone-Ts_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Prone Ts. 2. Lie face down (prone position) for Suspender Prone Ts. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'general_exercise', 'Suspender Prone Ts', 'squat, bench_press, deadlift', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('aadb331e-dfba-4ca7-906e-c8e65ce100f2', 'Seated March (Chair)', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. Secondary activation of your hip flexors provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Plyometric training builds explosive power that transfers to sports and daily activities.', '72591201', '72591201-Sitting-March-on-a-Chair-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting. Control the movement—avoid using momentum. Include this in your plyometrics training.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'marching', 'Seated March On A Chair', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('aafa881a-5c26-4d1b-9518-673cd65551a3', 'Plank Jack (Medicine Ball)', 'Core', 'Medicine Ball', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Medicine Ball Plank Jack is a core stabilization exercise that primarily targets your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. Building core stability helps with everything from heavy deadlifts to daily activities.', '76141201', '76141201-Medicine-Ball-Plank-Jack-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Hold a medicine ball at the appropriate position for Medicine Ball Plank Jack. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'plank', 'Medicine Ball Plank Jack', 'side_plank, dead_bug, hollow_hold', TRUE, 'medicine_ball', FALSE, 3, 60, 4, 70, 88, 95, 65),
('ab0395c1-a755-4f0e-ac45-5ec6bf3ec607', 'Long Arms Step Back', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Long Arms Step Back is an explosive exercise that combines cardiovascular training with dynamic stepping movements. You''ll also feel your quads working to support the movement. Plyometric training builds explosive power that transfers to sports and daily activities.', '88281201', '88281201-Long-Arms-Step-Back-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Long Arms Step Back. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Long Arms Step Back', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('ab04371d-738c-42e9-8ab5-2ac902e834fa', 'Clam (Resistance Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your glute med/abductors. Bands are joint-friendly and portable, perfect for any training environment. Leg training boosts metabolism and builds functional, real-world strength.', '57801201', '57801201-Resistance-Band-Clam-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Secure the resistance band appropriately for Resistance Band Clam. 2. Set up in the starting position for Resistance Band Clam. 3. Execute the movement with proper form, focusing on your glute med/abductors. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'hip_abduction', 'Clam', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('ab179f7b-2509-4d80-bb6c-cb743197e6c7', 'Seated Knee Raise (Resistance Band)', 'Core', 'Resistance Band', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Resistance Band Seated Knee Raise is a lower body raising exercise that targets your abs. Secondary activation of your hip flexors provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. Resistance bands provide accommodating resistance that increases through the range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '107531201', '107531201-Resistance-Band-Seated-Knee-Raise-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Seated Knee Raise. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Raise the weight in the prescribed direction for Resistance Band Seated Knee Raise. 4. Lower with control, maintaining tension throughout. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'leg_raise', 'Seated Knee Raise', 'crunch, plank, v_up', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('ab1a4f30-01e9-4998-a4a8-0a06734770b2', 'Seated Bent Arm Lateral Raise (Dumbbell)', 'Shoulders', 'Dumbbells, Flat Bench', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'This raising exercise works your lateral delts for improved shoulder strength and aesthetics. The seated position helps isolate the target muscles by removing momentum. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '105111201', '105111201-Dumbbell-Seated-Bent-Arm-Lateral-Raise_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Bent Arm Lateral Raise. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Raise your arms out to the sides until parallel to the floor. 4. Lower with control, maintaining tension throughout. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'lateral_raise', 'Seated Bent Arm Lateral Raise', 'shoulder_press, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('ab2407df-af78-4cf3-abec-519238f6708b', 'Drag Curl (Resistance Band)', 'Arms', 'Resistance Band', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. The forearms assist throughout the movement, making this a well-rounded exercise. Resistance bands provide accommodating resistance that increases through the range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '83271201', '83271201-Resistance-Band-Drag-Curl-(male)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Secure the resistance band appropriately for Resistance Band Drag Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'bicep_curl', 'Drag Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('ab243329-d6ee-4572-a350-67cfa50eb87b', 'Rear Deltoid Stretch', 'Shoulders', 'Bodyweight', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'Target your rear delts with the Rear Deltoid Stretch, an effective shoulder stretching exercise. You''ll also feel your upper back working to support the movement. No equipment needed—your body provides all the resistance. Strong shoulders improve overhead strength and support nearly all upper body movements.', '43011201', '43011201-Rear-Deltoid-Stretch-(female)_Shoulders-FIX2_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Set up in the starting position for Rear Deltoid Stretch. 2. Execute the movement with proper form, focusing on your rear delts. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'rear_delt', 'Rear Deltoid Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('ab2768f9-eb0c-419c-a5e9-3ff69726c1b0', 'Lying Abdominal Scissors Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Abdominal Scissors Crunch is a core crunching exercise that primarily targets your abs. You''ll also feel your hip flexors working to support the movement. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '90241201', '90241201-Lying-Abdominal-Scissors-Crunch-(male)_Waist-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Lie down in the appropriate position for Lying Abdominal Scissors Crunch. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Lying Abdominal Scissors Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('ab297e74-28c0-4de9-a8e2-5624a96764d1', 'Back Steps Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Back Steps Plank is a core stabilization exercise that primarily targets your abs. Your shoulders, lower back work as secondary movers, adding to the training stimulus. A strong core improves posture, protects your spine, and enhances all other lifts.', '72471201', '72471201-Back-Steps-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Set up a box or step platform at the appropriate height. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Back Steps Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('ab48a125-1974-4034-ac08-412a1d94e92f', 'Romanian Deadlift (Resistance Band)', 'Legs', 'Resistance Band', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. The glutes, lower back assist throughout the movement, making this a well-rounded exercise. Resistance bands provide accommodating resistance that increases through the range of motion. Lower body strength improves everything from walking to heavy compound lifts.', '75361201', '75361201-Resistance-Band-Romanian-Deadlift_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Secure the resistance band appropriately for Resistance Band Romanian Deadlift. 2. Push your hips back, lowering the weight along your legs with a flat back. 3. Lower until you feel a stretch in your hamstrings. 4. Drive hips forward to stand, squeezing glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'romanian_deadlift', 'Romanian Deadlift', 'deadlift, leg_curl, hip_thrust', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('ab4978f8-0189-4413-83c4-74a368313ddc', 'Cross Mountain Climber Kick (Against Wall)', 'Core', 'Wall', '{"Abs"}'::text[], '{"Hip Flexors","Shoulders"}'::text[], 'Build power and athleticism with this high-intensity kicking exercise that challenges your entire body. Your shoulders, core work as secondary movers, adding to the training stimulus. Great for improving athletic performance, burning calories, and building conditioning.', '88871201', '88871201-Cross-Mountain-Climber-Kick-against-Wall-(male)_Wa.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Position yourself at the appropriate distance from a wall. 2. From plank position, drive one knee toward your chest. 3. Quickly switch legs, bringing the other knee forward. 4. Continue alternating at a quick pace while maintaining plank form. 5. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 42, 9, 8, TRUE, TRUE, 'mountain_climber', 'Cross Mountain Climber Kick Against Wall', 'burpee, plank, high_knees', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('ab4a2801-9215-4950-995d-98fbfab90382', 'Landmine Single Arm Side Low Fly (Landmine)', 'Chest', 'Landmine Attachment, Barbell', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Target your chest with the Landmine Single Arm Side Low Fly, an effective flying movement for upper body strength. The front delts assist throughout the movement, making this a well-rounded exercise. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '67001201', '67001201-Landmine-Single-Arm-Side-Low-Fly-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. With a slight bend in your elbows, move the weight in a wide arc. 2. Squeeze your chest muscles at the center/top of the movement. 3. Return with control, feeling the stretch at the bottom. 4. Complete all reps on one side, then switch to the other side. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'chest_fly', 'Landmine Single Arm Side Low Fly', 'bench_press, incline_press, push_up', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('ab6264e0-c4be-4b28-93a6-1f9336b1a21b', 'Hanging Straight Leg Raise (Pull-Up Bar)', 'Core', 'Pull-Up Bar', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Hanging Straight Leg Raise is a lower body raising exercise that targets your abs. Your hip flexors work as secondary movers, adding to the training stimulus. Hanging adds a grip and core stability component to the exercise. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '4751201', '04751201-Hanging-Straight-Leg-Raise_Hips-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Grip the bar and hang with arms fully extended, engaging your shoulders. 2. Keeping legs mostly straight, raise them toward the ceiling. 3. Lower with control, stopping just before touching down. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'romanian_deadlift', 'Hanging Straight Leg Raise', 'deadlift, leg_curl, hip_thrust', FALSE, 'pull_up_bar', FALSE, 3, 60, 2, 70, 88, 95, 65),
('ab65a20d-a4e4-4037-ba00-db6c94124cc6', 'Reverse Crunch M', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Reverse Crunch M, focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '8721201', '08721201-Reverse-Crunch-m_waist.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Lift your hips off the floor by contracting your lower abs. 2. Bring your knees toward your chest, then lower with control. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Reverse Crunch M', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('ab6da7ff-9b25-45cd-a47a-9b200652eb69', 'Seated Hand To Knee Back Stretch', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'The Seated Hand To Knee Back Stretch is a flexibility exercise that targets your back, helping to release tension and improve range of motion. You''ll also feel your shoulders working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '81241201', '81241201-Seated-Hand-To-Knee-Back-Stretch-(female)_Stretchi.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Hand To Knee Back Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'back_stretch', 'Seated Hand To Knee Back Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('ab6e55ab-c42a-4a87-b4ed-c8e28534b4fc', 'Seated Overhead Triceps Extension (Chair)', 'Arms', 'Chair', '{"Triceps"}'::text[], '{"Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. Being seated provides stability, allowing you to focus on the working muscles. Arm strength supports grip, pulling, and pushing in compound movements.', '86541201', '86541201-Seated-Overhead-Triceps-Extension-on-a-Chair-(male.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Complete all reps with control before resting. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 67, 5, 7, FALSE, TRUE, 'tricep_extension', 'Seated Overhead Triceps Extension On A Chair', 'tricep_pushdown, close_grip_bench', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('ab6fb4f8-cda4-4532-b4ca-616b9162eec6', 'Incline Hammer Curl (Dumbbell)', 'Arms', 'Dumbbells, Incline Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. You''ll also feel your forearms working to support the movement. Using an incline changes the angle of resistance for varied muscle recruitment. The dumbbell variation provides freedom of movement and greater range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '24941201', '24941201-Dumbbell-Incline-Hammer-Curl-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Hammer Curl. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 95, 5, 7, FALSE, TRUE, 'incline_press', 'Incline Hammer Curl', 'bench_press, shoulder_press, chest_fly', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('ab750c25-38cd-4154-b2f0-c1135f91c40b', 'Single Leg Split Squat (Smith Machine)', 'Legs', 'Smith Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. The machine guides your movement path for safer, more controlled repetitions. Lower body strength improves everything from walking to heavy compound lifts.', '7681201', '07681201-Smith-Single-Leg-Split-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Single Leg Split Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 88, 7, 9, TRUE, FALSE, 'split_squat', 'Smith Single Leg Split Squat', 'Single Leg Split Squat', FALSE, 'smith_machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('ab7ae924-85eb-44a2-9a08-d2e7457f1f30', 'Up And Down', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Target your delts with the Up And Down, an effective shoulder movement exercise. This bodyweight exercise requires no equipment and can be done anywhere. Shoulder development enhances both performance and upper body aesthetics.', '48771201', '48771201-Up-and-Down_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Set up in the starting position for Up And Down. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Up And Down', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ab7c59c9-05d4-48b4-a0bc-955992f7cb8f', 'Lateral Raise (Resistance Band)', 'Shoulders', 'Resistance Band', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this raising movement focusing on your lateral delts. Bands are joint-friendly and portable, perfect for any training environment. Shoulder development enhances both performance and upper body aesthetics.', '91401201', '91401201-Resistance-Band-Lateral-Raise-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Lateral Raise. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'lateral_raise', 'Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('ab7f8ac1-8dd6-4524-97bd-0d2b003a08d9', 'Seated Hamstring Curl (Chair, Gymnastic Rings)', 'Legs', 'Gymnastic Rings, Chair', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'The Seated Hamstring Curl On A Chair targets your hamstrings through a controlled curling motion. Your forearms work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Lower body strength improves everything from walking to heavy compound lifts.', '91041201', '91041201-Sitting-Hamstring-Curl-on-a-Chair-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 43, 5, 7, FALSE, TRUE, 'leg_curl', 'Seated Hamstring Curl On A Chair', 'romanian_deadlift, hip_thrust', FALSE, 'gymnastic_rings', FALSE, 3, 60, 2, 68, 85, 85, 70),
('ab8055db-0566-4857-9de5-f9a48d94a35e', 'Kneeling One Side Archer Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Kneeling One Side Archer Push Up, an effective pushing movement for upper body strength. Your triceps, front delts work as secondary movers, adding to the training stimulus. Kneeling helps eliminate lower body momentum from the movement. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics.', '70511201', '70511201-Kneeling-One-Side-Archer-Push-up_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Complete all reps with control before resting. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Kneeling One Side Archer Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ab811ae4-32e7-4287-ac9b-1840491bc334', 'Around The World Lying On Floor', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build a stronger back with this movement movement targeting your delts. You''ll also feel your chest working to support the movement. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. A strong back improves posture, prevents injury, and balances pressing movements.', '82721201', '82721201-Around-the-World-Lying-on-Floor-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Position yourself on the floor for Around The World Lying On Floor. 2. Lie down in the appropriate position for Around The World Lying On Floor. 3. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', NULL, 'Static', 'Compound', 'Bilateral', NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, 'Neutral', 'Narrow', 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'around_world', 'Around The World Lying On Floor', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ab85c846-6643-4055-8e54-8761b63695a8', 'Butt Kick With Shoulder Tap', 'Legs', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{"Calves"}'::text[], 'Build power and athleticism with this high-intensity kicking exercise that challenges your entire body. You''ll also feel your hamstrings working to support the movement. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '96801201', '96801201-Butt-Kick-with-Shoulder-Tap-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Set up in the starting position for Butt Kick With Shoulder Tap. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'glute_kickback', 'Butt Kick With Shoulder Tap', 'high_knees, jumping_jack, running', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ab87f7ec-282d-4cdf-a425-b76e6620b094', 'Single Leg Split Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The barbell allows you to handle heavier loads for maximum strength gains. Leg training boosts metabolism and builds functional, real-world strength.', '991201', '00991201-Barbell-Single-Leg-Split-Squat_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Single Leg Split Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', 'Squat', 'Push', 'Compound', 'Unilateral', NULL, 4, NULL, 10, 10, NULL, 4, 'Standing', NULL, 'Overhand', 'Standard', 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 92, 7, 9, TRUE, FALSE, 'split_squat', 'Single Leg Split Squat', 'lunge, bulgarian_split_squat, squat', FALSE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('ab997da7-35a5-4104-a490-f1be698655e6', 'Standing Quadriceps Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Use this stretch to open up your quads area and enhance overall flexibility. Performing this standing challenges your balance and core engagement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '83721201', '83721201-Standing-Quadriceps-Stretch-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Stand tall with your feet firmly planted. 2. Move into the stretch position for Standing Quadriceps Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Standing Quadriceps Stretch', 'stretch_hip, stretch_hamstring', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('abade53e-dd37-4b2d-8a9c-9dd59de58323', 'Lying Chest Press (Plate Loaded)', 'Chest', 'Chest Press Machine', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. Secondary activation of your triceps, front delts provides additional muscle engagement. Performing this lying down removes momentum for stricter form. The fixed path allows you to focus purely on muscular effort. A well-developed chest contributes to upper body strength and aesthetics.', '36101201', '36101201-Lever-Lying-Chest-Press-(plate-loaded)-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Lying Chest Press. 2. Lie down in the appropriate position for Lever Lying Chest Press. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Continue for your target rep count, maintaining good form throughout. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'bench_press', 'Lever Lying Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('abaeff77-a5fd-409d-b8e4-855625b7c00a', 'Sled 45 Degrees Single Leg Press (Machine)', 'Legs', 'Leg Press Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Sled 45 Degrees One Leg Press is a pressing exercise that primarily loads your quadriceps. Your glutes work as secondary movers, adding to the training stimulus. Strong legs are the foundation for athletic performance and functional fitness.', '26091201', '26091201-Sled-45-degrees-One-Leg-Press-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Position your feet on the platform and release the safety. 2. Lower the weight by bending your knees, then press back up powerfully. 3. Complete all reps on one side, then switch to the other side. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 75, 7, 9, TRUE, FALSE, 'leg_press', 'Sled 45 Degrees Single Leg Press', 'squat, hack_squat, lunge', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('abaf941d-d5ac-421e-8e4b-a24048ac901c', 'Behind Neck Press (Smith Machine)', 'Shoulders', 'Smith Machine', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your delts. The machine guides your movement path for safer, more controlled repetitions. Shoulder development enhances both performance and upper body aesthetics.', '7471201', '07471201-Smith-Behind-Neck-Press_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Behind Neck Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'neck_exercise', 'Smith Behind Neck Press', 'Behind Neck Press', FALSE, 'smith_machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('abb4abd1-da6e-4f03-8be4-7230c49e1e40', 'Standing Side Handshakes', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. The standing position engages your core for stability. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '73571201', '73571201-Standing-Side-Handshakes-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Stand with feet about shoulder-width apart. 2. Move into the stretch position for Standing Side Handshakes. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Side Handshakes', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('abbb58d7-496f-450f-8165-b83c9c3f72d9', 'Landmine Romanian Deadlift (Landmine)', 'Legs', 'Landmine Attachment, Barbell', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. Secondary activation of your glutes, lower back provides additional muscle engagement. Lower body strength improves everything from walking to heavy compound lifts. Focus on controlled form throughout each repetition.', '42471201', '42471201-Landmine-Romanian-Deadlift-(VERSION-2)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Push your hips back, lowering the weight along your legs with a flat back. 2. Lower until you feel a stretch in your hamstrings. 3. Drive hips forward to stand, squeezing glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Landmine Romanian Deadlift', 'deadlift, leg_curl, hip_thrust', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('abbd99cd-838b-4a2a-a545-daba7791f007', 'Seated Neck Stretch', 'Neck', 'Bodyweight', '{"Neck"}'::text[], '{"Traps"}'::text[], 'The Seated Neck Stretch is a flexibility exercise that targets your neck, helping to release tension and improve range of motion. Secondary activation of your upper back provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Include this in your routine for better mobility and reduced muscle tension.', '79751201', '79751201-Seated-Neck-Stretch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Neck Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'neck_stretch', 'Seated Neck Stretch', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('abbee5b1-9602-4b02-83ca-d484e90c2d5b', 'V Hold (beginner Level)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '69661201', '69661201-V-Hold-(beginner-level)-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Hold the position for the prescribed time, maintaining tension. 2. Set up in the starting position for V Hold. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'general_exercise', 'V Hold', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('abc8fa92-4a82-427b-b382-8168e52055e7', 'Hyperextension (Dumbbell)', 'Back', 'Dumbbells, Hyperextension Bench', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Dumbbell Hyperextension is a hip-dominant extension exercise that targets your glutes. The hamstrings, lower back assist throughout the movement, making this a well-rounded exercise. Dumbbells allow each arm to work independently, helping correct imbalances. Strong legs are the foundation for athletic performance and functional fitness.', '73281201', '73281201-Dumbbell-Hyperextension-(male)_Hips-FIX2_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Hyperextension. 2. Raise your torso by extending at the lower back/hips. 3. Lower with control, maintaining tension. 4. Complete all reps with control before resting. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'back_extension', 'Hyperextension', 'good_morning, bird_dog, superman', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('abd7918a-d1a7-4bec-a7c4-7e1ecd8d3554', 'Lying Bent Legs Raise', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This raising exercise engages your abs for improved core stability and strength. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '54721201', '54721201-Lying-Bent-Legs-Raise_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Lie down in the appropriate position for Lying Bent Legs Raise. 2. Set up in the starting position for Lying Bent Legs Raise. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_exercise', 'Lying Bent Legs Raise', 'squat, leg_curl, calf_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('abdc2db7-785c-49e9-ba76-95d4c168b331', 'Plank Pass Through (Kettlebell)', 'Core', 'Kettlebell', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'This stabilization exercise engages your abs for improved core stability and strength. Secondary activation of your shoulders, lower back provides additional muscle engagement. Kettlebells are excellent for building functional, real-world strength. Core strength is foundational for athletic performance and injury prevention.', '72291201', '72291201-Kettlebell-Plank-Pass-Through_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Select an appropriately weighted kettlebell for Kettlebell Plank Pass Through. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'pass_through', 'Plank Pass Through', 'crunch, leg_raise, russian_twist, dead_bug', FALSE, 'kettlebell', TRUE, 3, 90, 4, 75, 88, 88, 78),
('abe25892-befb-4c90-8e8d-cf23d34c4670', 'Locust Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your full body, the Locust Pose helps improve mobility and prevent stiffness. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '63241201', '63241201-Locust-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Move into the stretch position for Locust Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'general_exercise', 'Locust Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('abe50346-bea2-447c-9de0-3854bdafac16', 'Standing Curl - Reverse Grip (Barbell)', 'Arms', 'Barbell', '{"Forearms"}'::text[], '{"Biceps"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Your forearms work as secondary movers, adding to the training stimulus. The standing position engages your core for stability. Using a barbell provides stability for progressive overload. Arm strength supports grip, pulling, and pushing in compound movements.', '1101201', '01101201-Barbell-Standing-Reverse-Grip-Curl_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Grip a barbell with hands at the appropriate width for Barbell Standing Reverse Grip Curl. 2. Begin in a standing position with good posture. 3. Use a reverse grip (opposite of the standard grip for this exercise). 4. Keep your elbows in a fixed position throughout the movement. 5. Curl the weight up by contracting your biceps, squeezing at the top. 6. Lower with control, resisting the weight on the way down. 7. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'bicep_curl', 'Standing Curl - Reverse Grip', 'Standing Curl - Reverse Grip', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
